import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAY: [CaseTemplate] = [ferryDeckStabbing, marinaHullCocaine, deerStandShooting, poolPartyDrowning, tractorTheftRing, ghostGunKit, promNightFentanyl, landlordRentThreat, caretakerSavingsMove, custodyExchangeFlight, rooftopPharmacyBreakIn, hospitalBillingIdentity, tavernTruckShots, fishPlantGhostPayroll, countyFuelDepotSkim, stagedCrashClaim, diningWitnessThreat, highSchoolPostThreat, bridgeRescueAssault, parkedAmbulanceJoyride]

    static let ferryDeckStabbing = SmallCases.make(
        key: "story.ferryDeckStabbing",
        category: .violent,
        headlines: ["Passenger Stabbed on Ferry Deck During Crossing", "Suspect Detained at the Dock"],
        law: "awdwikisi",
        threshold: 7,
        spec: "Assaulted {V} with a knife, inflicting serious injury, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was stabbed once in the side on the open deck of a ferry on {DATE} during a twenty-minute crossing. Crew held {D} at the dock. A folding knife was found in a life-vest bin. {DL} says {V} lunged first after an argument over a seat.",
        state: [E(.statement, 3, "Deckhand", "{D} was bent over {V} when the deckhand arrived."), E(.physical, 3, "Knife", "Folding knife in a life-vest bin with {V}'s blood.", .search), E(.forensic, 2, "Medical Report", "One wound, four inches deep, no organ damage.")],
        defense: [E(.statement, 1, "Lunge", "{DL} says {V} lunged first.")],
        role: "Ferry deckhand",
        exam: [.direct("What did you see on the open deck of the ferry on {DATE}?", "\"During a twenty-minute crossing, I came out and found {D} bent over {V}, who had been stabbed once in the side.\""), .direct("What did the crew do?", "\"We got {V} help and kept {D} with us until we reached the dock, where deputies took over. I held {D} at the dock until they arrived.\""), .direct("What was found on the boat?", "\"A folding knife in a life-vest bin with {V}'s blood on it. The medical report describes one wound, four inches deep, with no organ damage.\""), .direct("Where were you when the trouble started, and how did you get to the open deck?", "\"I was working the car deck below and heard shouting come down the stairwell. The crossing had left the dock at 3:10, and it was about 3:22 when I came up onto the open deck.\""), .direct("What condition was {V} in when you reached {V.him}?", "\"{V} was sitting against the rail holding {V.his} side, with blood coming through {V.his} fingers. {V.He} was awake and kept saying it hurt, so I pressed a towel against the wound until we docked.\""), .direct("Where was {D} and how did {D} act when you arrived?", "\"{D} was kneeling right beside {V} and did not argue when I asked {D.him} to sit by the rail. We kept {D.him} there until the ferry reached the dock at 3:40 and deputies took over.\""), .cross("Did you see the stabbing itself?", "\"No. I came out after it happened. I saw {D} bent over {V}, but I didn't see how it began.\""), .cross("{DL} says {V} lunged first over a seat, doesn't {D.he}?", "\"There was an argument about a seat, I heard that from passengers. I can't say who moved first.\""), .cross("Did {DL} try to leave the boat?", "\"No. A ferry in the middle of the water doesn't give you much choice. {D} stayed with us and didn't resist when we held {D.him}.\""), .cross("Did you hear anything about how the argument started?", "\"Only from passengers afterward, and their stories did not match. Two of them said it began at the dock over a seat, but nobody agreed on who raised their voice first.\""), .cross("Did {D} say anything to you while you waited for the dock?", "\"Yes, {D} said more than once that {V} came at {D.him} first. I wrote that in the crew log and repeated it to the deputies, because I had no way to test it myself.\"")],
        defenseRole: "Passenger on the upper deck",
        defenseExam: [.direct("Where were you on the ferry?", "\"On the upper deck, looking down at the open deck below. I could see the passengers who were arguing near the seats.\""), .direct("What did you see between {DL} and {V}?", "\"They argued, and {V} threw something at {D} first. Then things went fast. I didn't see everything.\""), .direct("What did you do?", "\"I stayed where I was. I didn't know what had happened until I saw the crew come running.\""), .direct("How long had you been on the upper deck, and what first drew your attention?", "\"I had been up there since we left the dock at 3:10. Raised voices drew my eyes down, and I leaned on the rail to watch the two of them argue near the seats.\""), .direct("Who seemed angrier during the argument?", "\"It looked mutual to me. Both of them were loud and pointing, but {V} was the one who kept stepping closer to {D} while {D} stayed near the rail.\""), .direct("What happened when the people gathered?", "\"Passengers crowded together and someone shouted for the crew. I saw the deckhand run in and kneel beside {V}, and I stayed up top because I did not want to get in the way.\""), .cross("How clearly could you see from above?", "\"Not perfectly. I was looking down from the upper deck, and people were crowded together. I can tell you what I remember.\""), .cross("Did you see the knife?", "\"No. I didn't see a knife. I only saw {V} throw something and then a lot of movement.\""), .cross("Did you see the stabbing?", "\"No. I saw the argument and then people gathered around. I didn't see the moment itself.\""), .cross("Could you hear what words were being said from where you stood?", "\"Not clearly. The wind and the engine were loud, so I caught tone and a few words, but I could not tell you every sentence.\""), .cross("You never saw the actual contact between {DL} and {V}, did you?", "\"No. Passengers moved in front of them right then and I lost sight. I only saw the aftermath, with {V} on the deck and {D} kneeling.\"")],
        theory: ("{D} stabbed a passenger.", "A defense."),
        allocution: "\"I never meant to hurt anyone.\"",
        truths: ("{DL}'s prints are on the knife handle.", "{V} had thrown a cup at {DL} first."),
        defendant: [.direct("What happened over the seat?", "\"We argued about a seat. It got loud. {V} came at me, and I was afraid. It all happened in a few seconds on the open deck.\""), .direct("Did you stab {V}?", "\"I had a knife in my hand when {V} lunged. I don't remember exactly what happened next. I never meant to seriously hurt anyone.\""), .direct("What did you do afterward?", "\"I stayed there and tried to help. I didn't run, and I didn't throw the knife overboard. I was in shock.\""), .direct("Where on the ferry were you before the argument, and who was near you?", "\"I was sitting on the open deck near the rail with my bag beside me. {V} was standing close by, and the seat was the only thing we were arguing about.\""), .direct("Describe the moment {V} came toward you.", "\"It was fast. {V} came at me with both arms out, and I was backed against the rail with nowhere to go on a moving boat. I was scared and everything blurred after that.\""), .direct("How did you feel once you saw {V} was hurt?", "\"Sick. I knelt down and kept telling {V} to stay with me. I did not leave, and I did not argue when the deckhand showed up and asked me to sit down.\""), .cross("The knife was found in a life-vest bin, wasn't it?", "\"Yes, I put it there. I panicked. I didn't want anyone to get hurt again, and I wasn't thinking.\""), .cross("{V} was stabbed once in the side, wasn't {V.he}?", "\"Yes. That's what they say. I wish it hadn't happened. I only wanted it to stop.\""), .cross("You could have walked away from the seat dispute, couldn't you?", "\"I could have. It was a seat. I should have let it go. I let it grow into something it should never have been.\""), .cross("You told the deckhand {V} came at you first, but nobody on the crew saw that, did they?", "\"No, they came after. That is why I keep telling everyone what I remember, because the crew only saw me kneeling next to {V}.\""), .cross("If you were only afraid and in shock, why did you hide the knife in a life-vest bin?", "\"I do not have a good answer. I was panicking and wanted it out of my hand and away from everyone, and the bin was right there. It was the wrong thing to do.\"")],
        openings: ("During a twenty-minute ferry crossing, {V} was stabbed once in the side on the open deck. Crew found {D} bent over {V}, and a folding knife with {V}'s blood was in a life-vest bin. The State will show the knife and the medical report.", "The defense will point you to an argument over a seat, a passenger who saw {V} throw something first, and a sudden fight in which {D} was afraid. This was not planned."),
        closings: ("One wound, four inches deep, a folding knife with {V}'s blood hidden in a life-vest bin, and {D} bent over {V}. {D} hid the knife and stayed to explain nothing.", "{V} lunged after an argument, and {D} reacted in a few seconds on an open deck. The State has not proved {D} did not act in fear."),
        timeline: [(-1, "A seat argument begins at the dock."), (0, "3:10 p.m.: the crossing starts."), (0, "3:22 p.m.: {V} is cut."), (0, "3:40 p.m.: {DL} is held at the dock.")],
        identified: "A deckhand and a knife.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided,
        impact: "I still can't lift my arm.",
        doctrines: ["selfDefense", "imperfectSelfDefense"])

    static let marinaHullCocaine = SmallCases.make(
        key: "story.marinaHullCocaine",
        category: .drugs,
        headlines: ["Cocaine Found Packed in Fishing Boat Hull at Marina", "Dog Alerts During Dock Inspection"],
        law: "traffickingCocaine",
        threshold: 7,
        spec: "Trafficked in 28 grams or more of cocaine by possession, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Deputies inspecting boats at a marina on {DATE} found brick-wrapped cocaine weighing 410 grams behind a hull panel of a fishing boat registered to {D}. {DL} says {D.he} bought the boat two weeks earlier and had never opened the panel. A dog alerted at about 10 a.m., the hull panel was opened at 10:30 a.m., and no fingerprints were found on the bricks.",
        state: [E(.forensic, 3, "Lab Report", "410 grams of cocaine."), E(.physical, 3, "Hull Panel", "Bricks behind a screwed-in panel.", .search), E(.document, 2, "Registration", "Boat registered to {D} two weeks earlier.")],
        defense: [E(.document, 1, "Bill of Sale", "Sale dated two weeks earlier; a prior owner's name.")],
        role: "Deputy",
        exam: [.direct("What did you find at the marina?", "\"During a boat inspection, a dog alerted at about 10 a.m. We opened a hull panel at 10:30 and found brick-wrapped cocaine behind it.\""), .direct("How much cocaine was there, and whose boat was it?", "\"The lab says 410 grams. The fishing boat is registered to {D}, and the registration was transferred to {D} two weeks earlier.\""), .direct("What was the panel like?", "\"It was screwed in and not an obvious access point. Anyone would have had to take it off to reach the bricks.\""), .direct("How did the dog come to alert on that boat?", "\"We were walking a detection dog down the slips on a routine inspection. At about 10 a.m. the dog stopped at that fishing boat, sat, and fixed on the stern near the hull panel.\""), .direct("What did you do after the alert?", "\"We told the registered owner's slip neighbor we needed to look, photographed the panel, and waited for a second deputy. At 10:30 a.m. we removed the screws and opened it.\""), .direct("Describe what was behind the panel.", "\"There were brick-shaped packages wrapped in plastic and tape, tucked into the hollow space behind the panel. We weighed and sent them to the lab, which reported 410 grams of cocaine.\""), .cross("Were any fingerprints found on the bricks?", "\"None. We found no fingerprints on the bricks, so we cannot tie them to anyone by prints.\""), .cross("The boat had a previous owner, didn't it?", "\"Yes. The bill of sale names a seller who owned the boat before {D}. I do not know what that person knew.\""), .cross("Did anyone see {D} open that panel?", "\"No. Nobody saw {D} open it, and there is no video of that.\""), .cross("Did the screws look like they had been turned recently?", "\"They were corroded. We had to work them with a driver and some force, and I cannot tell you when they were last removed.\""), .cross("What evidence ties {D} to those bricks beyond the registration?", "\"The registration and the bill of sale are the main things. I have no prints, no video, and no witness who saw {D} put anything behind that panel.\"")],
        defenseRole: "Marina mechanic",
        defenseExam: [.direct("Have you serviced that boat since {D} bought it?", "\"No. The boat has not come to my shop since the sale, so I have not worked on it for {D}.\""), .direct("Did you ever see that hull panel opened?", "\"Never. In all the time I have known that boat, I have not seen the panel taken off or the screws turned.\""), .direct("What was the condition of the panel screws?", "\"They were rusty from years in a marine setting. A panel like that does not get opened casually.\""), .direct("How long have you worked at this marina and what do you do?", "\"Eleven years. I repair engines and fix hull hardware for boats berthed here, so I know most of the boats and their quirks.\""), .direct("What do you know about that fishing boat before {D} bought it?", "\"It sat on the same slip for a couple of years under the previous owner and rarely went out. I worked on its engine once, and the panel was never part of any job.\""), .direct("Why do you say the panel does not get opened casually?", "\"Those screws sit in salt air and seize. To get one out you need a penetrating oil and patience, so the panel is usually left alone for years.\""), .cross("Did you inspect the boat before the sale?", "\"No. I did not inspect it for the sale. I only know it from regular marina traffic.\""), .cross("Could someone have opened it without you knowing?", "\"I suppose so. I cannot watch every slip at the marina all day.\""), .cross("Do you know {D} personally?", "\"Only as a customer at the marina. I have no strong opinion of {D} either way.\""), .cross("So you cannot say who put anything behind the panel or when?", "\"Correct. I never looked behind it, and I do not know what was there or when it got there.\""), .cross("You only knew {D} as a customer for two weeks, correct?", "\"That is about right. {D} said hello at the dock a few times and paid {D.his} slip fee on time, and that is the limit of what I know.\"")],
        theory: ("{D} had cocaine on the boat.", "A new owner."),
        allocution: "\"It was not supposed to be found.\"",
        truths: ("{DL} had texted a buyer's number three days earlier.", "The panel's screws were rusted shut."),
        defendant: [.direct("Did you know there was cocaine on your boat?", "\"No. I had no idea. I bought the boat two weeks earlier for fishing and never opened that panel.\""), .direct("Why did you buy the boat?", "\"For fishing. I wanted a boat to fish on weekends, and this one was priced fairly.\""), .direct("What do you say about the text to a buyer's number?", "\"It was about a different matter. It had nothing to do with the boat or drugs.\""), .direct("How did you find the boat and what did you pay for it?", "\"I saw it listed by a seller who was getting out of boating. I looked it over on the dock, paid the asking price, and signed the bill of sale two weeks before the inspection.\""), .direct("What did you do on the boat in those two weeks?", "\"Mostly cleaned it, learned the engine, and took it out twice on the sound. I never needed anything behind that panel, so I never touched it.\""), .direct("How did you react when the deputies told you what they found?", "\"I was stunned. I told them straight away that I had owned the boat two weeks and had no idea. I gave them the bill of sale from my truck.\""), .cross("Two weeks of owning the boat and you never looked behind the panel?", "\"I never opened it. There was no reason to. I was learning the boat, not taking it apart.\""), .cross("410 grams of cocaine was behind a panel on a boat you own. How is that not yours?", "\"It is not mine. I did not put it there, and I did not know about it. The previous owner is the person to ask.\""), .cross("You texted a number three days earlier. What was that about?", "\"It was a personal matter. I do not want to get into it, but it was not about drugs.\""), .cross("You are saying a stranger left 410 grams of cocaine on your boat and you never looked. Do you expect the jury to accept that?", "\"I expect them to look at the paper. The boat had another owner for years, and I did not own it long enough to open every panel.\""), .cross("Who were you texting three days earlier, and why won't you say?", "\"It was a private matter that I would rather not explain in open court. I know how that sounds, but it was not about the boat.\"")],
        openings: ("Deputies inspecting boats at a marina found 410 grams of brick-wrapped cocaine behind a screwed-in hull panel of a fishing boat registered to {D} just two weeks earlier.", "{D} bought a fishing boat and never opened that panel. The defense will show no fingerprints on the bricks and a previous owner who is named on the bill of sale."),
        closings: ("A dog alert, a hull panel, 410 grams of cocaine, and a boat that is registered to {D}. The owner is responsible for what is hidden aboard.", "Two weeks of ownership, a panel that was rusted shut, and no fingerprints on any brick. The State has not shown that {D} ever knew what was hidden there."),
        timeline: [(-14, "{DL} buys the boat."), (0, "10 a.m.: the dog alerts."), (0, "10:30 a.m.: the panel is opened."), (0, "11 a.m.: {DL} is arrested.")],
        identified: "The registration and lab.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact", "searchSeizure"])

    static let deerStandShooting = SmallCases.make(
        key: "story.deerStandShooting",
        category: .violent,
        headlines: ["Hunter Shoots at Rival's Tree Stand and Wounds Him", "Dispute Over Hunting Lease Preceded Shot"],
        law: "awdwisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon, a rifle, inflicting serious injury, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was wounded in the shoulder on {DATE} when a rifle shot struck {V.his} tree stand. {D} was in a stand a quarter mile away and says {D.he} fired at a deer. A message from {D} a week earlier told {V} to stay off the lease.",
        state: [E(.forensic, 3, "Ballistics", "The bullet matches {D}'s rifle."), E(.document, 2, "Message", "'Stay off this lease or else.'"), E(.forensic, 2, "Medical Report", "Shoulder wound.")],
        defense: [E(.statement, 1, "Deer", "{DL} says {D.he} fired at a deer.")],
        role: "Wildlife officer",
        exam: [.direct("What did you learn about the shooting on {DATE}?", "\"{V} was wounded in the shoulder when a rifle shot struck {V}'s tree stand. {D} was in a stand about a quarter mile away.\""), .direct("What did ballistics show?", "\"The bullet matches {D}'s rifle. That's the report I received, and it ties the shot to {D}'s gun.\""), .direct("What history was there between {DL} and {V}?", "\"A week earlier, {D} sent {V} a message saying, 'Stay off this lease or else.' That message is in evidence.\""), .direct("What did you do when you arrived at the lease that morning?", "\"I got there after the 6:50 call for help. I walked to {V}'s stand with deputies, photographed the splintered wood where the bullet hit, and marked the direction it came from.\""), .direct("How did you determine which stand the shot came from?", "\"I lined up the entry mark in the tree stand with the lane of woods, and it pointed toward {D}'s stand. We recovered the bullet and sent it to the lab.\""), .direct("What did {D} tell you when you spoke at 9 a.m.?", "\"{D} said {D.he} fired once at a deer near first light and did not know anyone else was hunting that side. {D} gave up the rifle without any trouble.\""), .cross("{DL} says {D.he} fired at a deer, doesn't {D.he}?", "\"Hunters do fire at deer. But a quarter mile is a long way for a shot to cross to another stand.\""), .cross("Did anyone see {DL} fire at {V}?", "\"No. There was no witness to the shot itself. I have the ballistics and the message, but nobody saw {D} aim at {V}.\""), .cross("Was {V} badly hurt?", "\"A shoulder wound, which the medical report documents. {V} was lucky it wasn't worse.\""), .cross("Did you find any sign of a deer in that line of fire?", "\"There were some tracks and a little blood near the line, and I noted it. I cannot tell you when they were made or what animal left them.\""), .cross("Is it unusual for a stray bullet to travel that far?", "\"Not unusual for a rifle. A round can carry well past a quarter mile, which is why hunters are taught to know their backstop.\"")],
        defenseRole: "Hunting partner",
        defenseExam: [.direct("Were you with {DL} that day?", "\"Yes. I was in the stand next to {D}'s. We were hunting together on the lease that morning.\""), .direct("What did {DL} say before the shot?", "\"{D} said {D.he} saw a deer. {D} whispered it and took the shot. It sounded like any ordinary hunting moment.\""), .direct("How did {DL} react when learning about {V}?", "\"{D} was stunned. {D} went pale and said {D.he} had no idea anyone was in that direction.\""), .direct("How long have you hunted with {DL}?", "\"Close to six years, mostly on this lease. {D} is careful with the rifle in my experience and always asks where everybody is sitting.\""), .direct("What was the light like at 6:40 that morning?", "\"Barely gray. You could make out outlines but not details. At that hour a moving shape in brush can look like several different things.\""), .direct("What did {DL} do right after the shot?", "\"{D} stayed still and listened, then said it looked like the deer ran. When the shouting started, {D} lowered the rifle right away and climbed down.\""), .cross("Were you with {DL} at the moment of the shot?", "\"In the next stand, yes. I couldn't see exactly where {D} pointed. I heard the shot and not much else.\""), .cross("Did you see the deer?", "\"I didn't. {D} said there was one. I didn't see it myself, so I only know what {D} told me.\""), .cross("Did {DL} talk about {V} that morning?", "\"Not much. {D} grumbled about the lease at some point. Nothing specific about shooting anybody.\""), .cross("You did not see where the bullet went, did you?", "\"No. I heard the crack and saw nothing downrange. I only know what {D} told me about what {D.he} aimed at.\""), .cross("Did {DL} ever mention the dispute with {V} while you were in the stand?", "\"Briefly, the week before. {D} was irritated about the lease and complained about it, but I never heard {D.him} talk about hurting anyone.\"")],
        theory: ("{D} shot a rival.", "A deer."),
        allocution: "\"I never saw the stand.\"",
        truths: ("{DL} had texted 'or else' to {V}.", "Tracks and blood from a deer were found in the line."),
        defendant: [.direct("What were you doing in the stand that day?", "\"I was hunting. I saw a deer and I took a shot. I didn't know anyone was in the other stand.\""), .direct("Did you mean to shoot at {V}?", "\"No. I would never shoot at another person. I fired at a deer, and I was horrified to learn the bullet hit near {V}.\""), .direct("Why did you send {V} that message?", "\"We argued about the lease. I was upset and I wrote something I didn't mean. I regret the words.\""), .direct("How far apart were the two stands, and could you see {V}'s stand?", "\"About a quarter mile. In the gray light I could see tree trunks and brush, but I did not make out {V}'s stand and did not think anyone was out there.\""), .direct("Tell the jury what you saw right before you fired.", "\"Movement in the brush that looked like a deer. I settled the rifle, took one shot, and saw nothing more. I did not walk over to check because I thought I had missed.\""), .direct("How did you learn {V} had been hit?", "\"Around 6:50 I heard shouting and then saw deputies. When they told me a bullet from my rifle may have hit {V}, I felt sick and gave them the gun.\""), .cross("'Stay off this lease or else' is a threat, isn't it?", "\"It sounds like one. I was angry about the lease. I meant to scare {V.him} off, not hurt anyone.\""), .cross("The bullet came from your rifle, didn't it?", "\"That's what they say. I did fire. I was aiming at a deer, and I don't know how it went that way.\""), .cross("A quarter mile is a long shot, isn't it?", "\"It's long, but I'm comfortable at that distance. I wouldn't have fired if I'd seen anyone in the way.\""), .cross("You wrote 'or else' to {V}, and then {V} got shot a week later. Why should the jury see that as coincidence?", "\"Because I was angry about a lease, not planning anything. I told {V} to stay off, and the shot that morning was at a deer.\""), .cross("You never confirmed that you hit a deer, did you?", "\"No. I looked for it later and did not find one. I thought I had missed, and I did not follow up the way In hindsight, yes.\"")],
        openings: ("{V} was shot in the shoulder in a tree stand, and the bullet matches {D}'s rifle, fired from a stand a quarter mile away. A week earlier, {D} had written, 'Stay off this lease or else.' The State will show the ballistics and the message.", "Jurors will also see a hunter who fired at a deer, a hunting partner who was right there, and a quarter mile of woods between two stands. Missing a target is not attempting to kill."),
        closings: ("A bullet from {D}'s rifle, a message telling {V} to stay off the lease or else, and a wound to the shoulder. A hunter knows where a shot is going, and {D} is the only one who fired.", "A deer, a long shot, and a partner who heard it. The State has not proved {D} aimed at {V}. A bad message about a lease is not an intent to shoot."),
        timeline: [(-7, "The lease dispute."), (0, "6:40 a.m.: the shot."), (0, "6:50 a.m.: {V} calls for help."), (0, "9 a.m.: {DL} is questioned.")],
        identified: "Ballistics and a message.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        impact: "I was hunting with my son.",
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male, "V": .male])

    static let poolPartyDrowning = SmallCases.make(
        key: "story.poolPartyDrowning",
        category: .violent,
        headlines: ["Boy Drowns at Backyard Pool Party", "Host Had Been Drinking, Neighbors Say"],
        law: "invManslaughter",
        threshold: 6,
        spec: "Unintentionally killed {V} without malice through culpable negligence, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a seven-year-old, drowned in a backyard pool on {DATE} during a birthday party hosted by {D}. Guests said {D} was drinking at the grill and no adult watched the pool for at least twenty minutes. {DL} says a hired lifeguard was supposed to be there.",
        state: [E(.statement, 3, "Guest", "No adult was at the pool for twenty minutes."), E(.forensic, 3, "Autopsy", "Drowning."), E(.document, 2, "Text Thread", "{DL} told a guest to watch the pool.")],
        defense: [E(.document, 1, "Lifeguard Contract", "A booking for a guard, unsigned.")],
        role: "Party guest",
        exam: [.direct("What did you see at the birthday party?", "\"{D} was at the grill with a beer. The children were swimming in the backyard pool, and I did not see an adult at the pool.\""), .direct("How long was the pool unwatched?", "\"At least twenty minutes. I looked around and realized no adult was near the water at all.\""), .direct("Was a lifeguard there?", "\"No. There was no guard that I saw, and nobody mentioned one to me that day.\""), .direct("Where were you standing relative to the pool during the party?", "\"I was near the patio table with a plate of food. From there I could see the grill clearly and the pool only at an angle.\""), .direct("When did you realize something was wrong?", "\"Around 3:15, a guest yelled that a child was on the bottom of the pool. People ran over and a couple of adults pulled {V} out and started chest compressions.\""), .direct("What did {D} do when {D.he} found out?", "\"{D} dropped the tongs and ran to the pool, then called 911 while others worked on {V}. {D} looked terrified. Paramedics arrived and took {V} away.\""), .cross("Did {D} tell someone to watch the pool?", "\"There was a text thread where {D} asked a guest to watch the pool. I did not see that text that day.\""), .cross("How many adults were at the party?", "\"Quite a few. People were in the kitchen and at the grill, and everyone assumed someone else was watching.\""), .cross("Did you watch the pool yourself?", "\"Not the whole time. I will admit I looked away, and I think about it often.\""), .cross("Did you see {D} drink more than a beer or two?", "\"I saw {D} with a beer in hand most of the afternoon. I did not count them, and I will not guess at a number.\""), .cross("If you were worried about the pool, why didn't you say something to {D}?", "\"I assumed somebody had it. Honestly, with that many adults around, I figured the pool was covered. I wish I had asked.\"")],
        defenseRole: "Party guest",
        defenseExam: [.direct("What did {D} ask you to do?", "\"{D} asked me to keep an eye on the pool while {D} worked the grill. I said yes.\""), .direct("Did you watch the pool?", "\"I started to. Then I got pulled into a conversation in the kitchen and looked away. I was away for longer than I thought.\""), .direct("Did you know a lifeguard had been planned?", "\"I heard {D} mention a guard was supposed to come. I did not see one, and I did not think to ask.\""), .direct("How did you end up being asked to watch the pool?", "\"{D} came over by the kitchen around 2:30 and asked if I would keep an eye on the water while the burgers were cooking. I said I would.\""), .direct("What pulled you away from the pool?", "\"A friend started telling me about a family problem and I stepped into the kitchen to listen. I told myself it would be a minute.\""), .direct("What did you do when you heard the shout?", "\"I ran out. Two adults had already lifted {V} onto the deck and were doing CPR. I dialed 911 on my phone while someone else counted.\""), .cross("So you were the person asked to watch, and you looked away?", "\"Yes. I looked away. I feel awful about it, and I have said so.\""), .cross("Did {D} check on you or the pool?", "\"I did not see that. {D} was at the grill, and I did not see {D} come to the pool.\""), .cross("How long was the child in the water before anyone noticed?", "\"I cannot say exactly. It was several minutes, and it happened fast.\""), .cross("Did you tell {D} you were leaving the pool?", "\"No. I did not say anything. I just walked inside and assumed it would be fine for a minute.\""), .cross("How many kids were in the pool at the time you stepped away?", "\"Several, maybe six or seven, mostly splashing around the shallow end. It looked loud and ordinary, which is part of why I got comfortable.\"")],
        theory: ("{D} let a child drown.", "A hired guard."),
        allocution: "\"I will never forgive myself.\"",
        truths: ("{DL} had five beers over two hours.", "The guard's invoice was never paid."),
        defendant: [.direct("Why was there no lifeguard at the party for your child?", "\"I hired one, and the guard cancelled. I did not have time to find another, so I asked a guest to watch.\""), .direct("Were you drinking at the grill?", "\"Two beers. I was serving food, and I was not drunk.\""), .direct("What did you do to protect the children?", "\"I sent a text asking a guest to watch the pool. I assumed someone read it and was watching.\""), .direct("How did you plan to keep the children safe around the pool?", "\"I booked a lifeguard weeks ahead for the whole afternoon. When that fell through the morning of the party, I texted a guest to watch the pool and told the kids the rules.\""), .direct("What was your role at the party?", "\"I was the host and the cook. I had burgers on the grill for about thirty people, and I was going back and forth between the grill and the kitchen.\""), .direct("What did you do when you were told {V} was in the water?", "\"I ran to the pool and helped pull {V} out. Someone started compressions while I called 911, and I stayed on the line until the paramedics got there.\""), .cross("Guests say you had more than two beers, don't they?", "\"It may have been more. I was busy and I was not counting.\""), .cross("You did not check that anyone was at the pool, did you?", "\"No. I assumed the person I texted was there. I should have gone to look.\""), .cross("A child died in your pool at your party. Whose job was it to make sure someone was watching?", "\"Mine. I was the host, and I think about that every day.\""), .cross("You say you hired a guard, but the contract was never signed, was it?", "\"It was a booking and I had an invoice. The guard cancelled and I never paid, so the paperwork is not complete.\""), .cross("You were at the grill for the entire stretch when the pool was unwatched, weren't you?", "\"Yes. I was at the grill, and I am not going to pretend otherwise. I should have walked over and looked.\"")],
        openings: ("{V}, a seven-year-old, drowned in a backyard pool during a birthday party hosted by {D}. Guests say {D} was drinking at the grill and no adult watched the water for at least twenty minutes.", "A hired lifeguard cancelled, and {D} asked a guest to watch the pool by text. The defense will show a host who took steps, and a tragedy no one intended."),
        closings: ("No lifeguard, no adult at the pool for twenty minutes, and a host with a beer at the grill. A child is dead because no one was watching the water.", "{D} hired a guard, who cancelled, and then asked someone to watch. Everyone shares a terrible loss, but a failed plan is not the same as culpable negligence."),
        timeline: [(-14, "{DL} books a guard."), (0, "2 p.m.: the party starts."), (0, "3:15 p.m.: {V} is found."), (0, "3:40 p.m.: {V} is pronounced dead.")],
        identified: "Guest accounts and records.",
        aggravating: [],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .sympathetic,
        impact: "He was our only son.",
        doctrines: ["lesserIncluded"],
        genders: ["V": .male])

    static let tractorTheftRing = SmallCases.make(
        key: "story.tractorTheftRing",
        category: .property,
        headlines: ["Three Tractors Stolen From Rural Farms in One Month", "Trailer Tracked to Out-of-State Seller"],
        law: "felonyLarceny",
        threshold: 7,
        spec: "Stole three tractors valued at $91,000 belonging to {V} and others, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Three tractors worth $91,000 were taken from rural farms over a month. A trailer rented by {D} was seen on a farm road. Serial plates were ground off one machine sold at an auction. {DL} says {D.he} hauled the machines for a customer.",
        state: [E(.document, 3, "Trailer Rental", "Rented by {D} on the dates."), E(.physical, 3, "Ground Plate", "Serial plate ground off the auction tractor."), E(.digital, 2, "Phone Location", "{DL}'s phone near each farm.")],
        defense: [E(.statement, 1, "Hauler", "{DL} says {D.he} was hired to haul.")],
        role: "Sheriff's detective",
        exam: [.direct("How did {D} come to your attention?", "\"Three tractors worth $91,000 were taken from rural farms over a month, and a trailer rented by {D} was seen on a farm road.\""), .direct("What did you find on the auction tractor?", "\"One of the stolen machines was sold at an auction, and its serial plate had been ground off.\""), .direct("What does {D}'s phone show?", "\"{D}'s phone was near each farm on the nights the tractors were taken. The rental records show the trailer was rented for those same dates.\""), .direct("How did the three thefts line up with each other?", "\"All three tractors left farms off rural roads over about a month, always at night, and none of the owners saw anything. The third machine disappeared in week four and was at an auction the next week.\""), .direct("What did the trailer rental records add?", "\"The rental company's file shows {D} rented a flatbed trailer on dates that match the thefts, and a farm road camera caught a similar trailer near one of the farms.\""), .direct("What happened at the auction?", "\"One tractor came through in week five with its serial plate ground to a smooth patch. An auction clerk had the consignment form, and it carried {D}'s name.\""), .cross("Who did {D} say hired {D.him}?", "\"{D} gave a name of a customer who paid for hauling. We have been unable to find that person.\""), .cross("Is hauling equipment for a customer illegal?", "\"No. A person can haul equipment for hire. What matters is whether {D} knew it was stolen.\""), .cross("Did anyone see {D} take a tractor?", "\"No. We have no witness to that. We have a trailer, phone data, and the auction.\""), .cross("Did {D} try to hide the name on the consignment form?", "\"No, the form carries {D}'s real name. I can only tell you what the form shows, and I have no proof of why {D} used it.\""), .cross("Is a phone near a farm the same as a phone at the tractor?", "\"No. Location data puts the phone within a few hundred yards of each farm, which is consistent with {D} being there, but it does not show {D} touching a machine.\"")],
        defenseRole: "Auction clerk",
        defenseExam: [.direct("Who consigned the tractor with the ground plate?", "\"A person with a rental trailer brought it in. The consignment form lists {D}.\""), .direct("Was the plate already ground off?", "\"Yes, it was ground off when it arrived. I noted it at the time.\""), .direct("How did {D} act when consigning it?", "\"{D} was calm and ordinary. {D} did not seem to be hiding anything.\""), .direct("How long have you been an auction clerk, and what does the consignment desk do?", "\"Nine years. We take the paperwork for each machine, record who brings it in, and check the identification before a lot gets a number.\""), .direct("What did {D} bring with the tractor?", "\"A flatbed trailer and a signed consignment form. {D} gave a clear answer to every question I asked and handed over identification without any hesitation.\""), .direct("Did {D} try to avoid the office or rush?", "\"No. {D} waited in line with everyone else, filled out the form, and left a phone number. There was nothing furtive about it.\""), .cross("Did {D} say where the tractor came from?", "\"{D} said it was from a customer. I did not ask more than that.\""), .cross("Do you normally check serial plates?", "\"Usually. I should have caught it, and I did not look closely.\""), .cross("Did you see anyone else with {D}?", "\"No. {D} came alone with the trailer.\""), .cross("You noticed the plate was ground and still accepted the machine?", "\"Yes, and that was a lapse. We normally flag a missing plate, and I wrote a note on it but let the lot go through.\""), .cross("How many consignors do you see in a week?", "\"Dozens. Most blur together. I remember this one because of the plate, and I cannot tell you the details of every conversation.\"")],
        theory: ("{D} hauled stolen tractors.", "A paid hauler."),
        allocution: "\"I should have asked more.\"",
        truths: ("{DL} was paid $4,000 cash.", "The customer's number is saved in {DL}'s phone from months earlier."),
        defendant: [.direct("Did you steal those tractors?", "\"No. I hauled them for a customer. I did not take them from anyone's farm.\""), .direct("How were you paid?", "\"In cash. The customer asked to pay that way, and I did not think anything of it.\""), .direct("Did you grind the plate off?", "\"Not me. It was ground off when I got it, and I did not touch the plate.\""), .direct("How did you meet the customer who hired you?", "\"The customer called me about hauling heavy equipment and said there would be several jobs. I took the work because hauling is what I do and the money was good.\""), .direct("Walk the jury through one pickup.", "\"I rented the trailer, drove to the farm road the customer named, loaded the tractor with the ramps, and drove it where I was told. Nobody stopped me and nothing looked wrong.\""), .direct("Why did you bring a tractor to the auction in your own name?", "\"Because I was told to consign it, and I had nothing to hide. If I had known it was stolen, I would never have put my name on any paper.\""), .cross("Why would a customer insist on cash?", "\"The customer said cash was preferred. I did not question it, and I should have.\""), .cross("Your phone was near each farm. How do you explain that?", "\"I went to pick up the machines. That is where the customer told me to go.\""), .cross("You cannot produce this customer, can you?", "\"I have a number, but I cannot reach the person. I know it sounds convenient.\""), .cross("You rented a trailer in your own name and hauled three machines in a month. You never asked where they came from?", "\"I asked once, and the customer said they were the customer's own machines. I took that at its word, and I should have pushed harder.\""), .cross("A ground-off serial plate did not make you suspicious?", "\"It was already ground when I loaded it. I will admit it should have bothered me. I thought maybe the plate had been worn down in the field.\"")],
        openings: ("Three tractors worth $91,000 were stolen from rural farms over one month. A trailer rented by {D} was seen on a farm road, {D}'s phone was near each farm, and one tractor reached an auction with its serial plate ground off.", "{D} hauled machines for a customer and never knew they were stolen. The defense will show a haul-for-hire job, and no one who saw {D} take a thing."),
        closings: ("Three farms, three tractors, a rented trailer, a phone near each farm, and a ground-off plate. The pieces fit, and {D} is at the center of each.", "{D} hauled for a customer, was paid in cash, and used {D.his} own name at the auction. The State has not proved {D} knew the machines were stolen."),
        timeline: [(-30, "The first tractor disappears."), (0, "Week 4: the third tractor is taken."), (0, "Week 5: an auction sale."), (0, "Week 5: {DL} is arrested.")],
        identified: "Rental and phone data.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"])

    static let ghostGunKit = SmallCases.make(
        key: "story.ghostGunKit",
        category: .violent,
        headlines: ["Convicted Felon Builds Untraceable Rifle From Kit", "Buyer Turns Out to Be Undercover Deputy"],
        law: "felonFirearm",
        threshold: 8,
        spec: "Possessed a firearm after a felony conviction, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D}, with a prior felony, was arrested on {DATE} after selling a kit-built rifle with no serial number to an undercover deputy. {DL} says {D.he} was only holding it for a friend. A deputy arranged the buy three days earlier, and the handoff took place at 11 a.m. for $900. {D} was arrested two minutes later, and a search of {D.his} garage followed at 1 p.m.",
        state: [E(.video, 3, "Body Camera", "{D} hands the rifle to the deputy."), E(.document, 3, "Certified Record", "{D}'s prior felony."), E(.physical, 2, "Rifle", "No serial number; {D}'s fingerprints.", .search)],
        defense: [E(.statement, 1, "Friend", "{DL} says the rifle was a friend's.")],
        role: "Undercover deputy",
        exam: [.direct("How did you set up the buy with {DL}?", "\"I arranged it three days earlier, undercover. The handoff happened at 11 a.m. for $900, and I wore a body camera.\""), .direct("What does the body camera show?", "\"{D} handing me a rifle. The rifle had no serial number and was kit-built. {D} was arrested about two minutes after the handoff.\""), .direct("What else did you find?", "\"A certified record of {D}'s prior felony, and the rifle carried {D}'s fingerprints. A search of {D}'s garage followed at 1 p.m.\""), .direct("What did {D} say at the meeting about the rifle?", "\"{D} told me it was ready to go, no serial number, and that I would not have to worry about paperwork. {D} quoted $900 and said to bring cash.\""), .direct("Describe the handoff itself.", "\"We met at 11 a.m. in a parking area. {D} carried the rifle out in a bag, handed it to me, and I handed over the marked $900. Takedown teams moved in about two minutes later.\""), .direct("What was found in the garage?", "\"At 1 p.m., deputies searched the garage under a warrant and found tools and parts that can be used to complete a kit rifle. I did not see anything that was assembled on site.\""), .cross("{DL} says it was a friend's rifle, doesn't {D.he}?", "\"{D} was the one who handed it over and took the $900.\""), .cross("Did you see {DL} build the rifle?", "\"No. I have no evidence of the build itself. I only know what {D} sold me and what was found afterward.\""), .cross("Did {DL} say who the friend was?", "\"I don't recall a name. {D} said it was for a friend. I didn't get one I could follow up on.\""), .cross("Did the garage search turn up any receipts for building this rifle?", "\"I did not see any receipts. The tools were consistent with kit work, but tools alone do not tell me who used them or when.\""), .cross("Did {D} ever say the rifle was {D.his} own build?", "\"Not in those words. {D} described it as ready to go and set the price. {D} never told me when or where it was put together.\"")],
        defenseRole: "Garage neighbor",
        defenseExam: [.direct("Do you live next to {DL}'s garage?", "\"Yes, right next door. I've lived here a while and I see {D} come and go a lot.\""), .direct("Have you seen anyone building things there?", "\"Never. I haven't seen guns or builds or tools out. It's always been quiet as far as I can tell.\""), .direct("What kind of neighbor is {DL}?", "\"Friendly, as far as I know. We wave. I've never had a problem with {D}.\""), .direct("How close is your garage to {D}'s?", "\"Our driveways share a fence line. I can hear when the garage door goes up and I walk past it most evenings when I take out the trash.\""), .direct("What have you seen going into {D}'s garage over the past year?", "\"Mostly lawn equipment and a car now and then. A few friends visit on weekends. Nothing that stood out to me as unusual.\""), .direct("Did you ever hear machinery or work noise from there?", "\"Normal hand-tool noise. Some drilling or sawing, which is what you hear from any garage. I never heard anything that sounded like a workshop for guns.\""), .cross("Do you watch {DL}'s garage?", "\"No. I'm at work most days. I don't keep an eye on the neighbors, so I wouldn't know.\""), .cross("Could someone have built something inside the garage?", "\"I suppose so. The garage door is usually down. I couldn't see in.\""), .cross("Do you know what happened on the day of the sale?", "\"No. I wasn't there at the handoff.\""), .cross("So you cannot say what was inside the garage on any given day?", "\"That is right. The door is usually shut, and I do not look in. I only know what I can hear and see from outside.\""), .cross("Do you know any of {D}'s friends by name?", "\"A couple by sight, not by name. If someone had stored something there, I would not necessarily have noticed.\"")],
        theory: ("{D} sold a felon-built rifle.", "A holder."),
        allocution: "\"I messed up.\"",
        truths: ("Build tools were in {DL}'s garage.", "A text on {DL}'s phone shows a friend asking to store the rifle."),
        defendant: [.direct("How did you end up handing over the rifle?", "\"A friend asked me to hold it, and then a buyer came along. I thought I was doing the friend a favor by passing it on.\""), .direct("Did you build the rifle?", "\"No. It wasn't mine. I was only holding it for a friend, and I never had a hand in putting it together.\""), .direct("Did you know you couldn't have a firearm?", "\"I knew I had a prior. That's why I should have refused. I made a bad decision to help.\""), .direct("How did your friend come to ask you to hold the rifle?", "\"My friend showed up with a bag one evening and asked if I could keep it in the garage for a while. I said yes and did not look closely.\""), .direct("What did you think when the buyer called?", "\"The buyer wanted a rifle and I knew my friend wanted to get rid of it. I thought I was helping out by making the introduction and passing it along.\""), .direct("What happened when the deputies arrested you?", "\"It was over in a couple of minutes. They put me on the ground, and I told them right away it was not mine. I did not fight them.\""), .cross("You took $900, didn't you?", "\"Yes. I took the money. I told myself I would give it to my friend. I see how that looks.\""), .cross("Your fingerprints are on the rifle, aren't they?", "\"They are. I held it. That doesn't mean I built it or that it was mine.\""), .cross("You can't give the friend's name, can you?", "\"I can, but I don't want to. I know that makes it worse, and I'm sorry.\""), .cross("You are a convicted felon who handled a rifle and took cash for it. Why not just say no?", "\"I should have said no. I thought of it as a favor and I ignored the law I knew about, and I accept that.\""), .cross("The tools in your garage were used for what, if not building?", "\"I have tools for all kinds of projects. My friend may have used some of them, but I never put that rifle together.\"")],
        openings: ("{D}, who has a prior felony, handed a kit-built rifle with no serial number to an undercover deputy at 11 a.m. for $900 and was arrested two minutes later. The State will show the body camera, the certified record, and the rifle.", "The defense will present someone who says the rifle belonged to a friend, a neighbor who never saw any building, and a person who made a poor choice in trying to help."),
        closings: ("A rifle with no serial number, $900 in hand, and a prior felony on record. {D}'s fingerprints are on the rifle, and the camera shows the handoff.", "The rifle was a friend's, and {D} never built it. The State has not proved {D} owned it, and a bad favor for a friend is not a plot."),
        timeline: [(-3, "The deputy arranges the buy."), (0, "11 a.m.: the handoff."), (0, "11:02 a.m.: arrest."), (0, "1 p.m.: garage search.")],
        identified: "Body camera and records.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"])

    static let promNightFentanyl = SmallCases.make(
        key: "story.promNightFentanyl",
        category: .drugs,
        headlines: ["Teen Dies After Pill Bought on Prom Night", "Messages Name Seller as a Classmate's Cousin"],
        law: "deathByDistribution",
        threshold: 8,
        spec: "Unlawfully sold a controlled substance that caused the death of {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a seventeen-year-old, died on {DATE} after taking a pill bought outside a prom after-party. Messages tied the sale to {D}, who sold counterfeit pills pressed with fentanyl. {DL} says {D.he} was not there that night.",
        state: [E(.forensic, 3, "Toxicology", "Fentanyl at lethal level."), E(.digital, 3, "Messages", "{D} arranges a sale to {V}'s friend."), E(.document, 2, "Pharmacy Image", "The pill matches counterfeit pills seized earlier.")],
        defense: [E(.statement, 1, "Absent", "{DL} says {D.he} was at work.")],
        role: "Overdose investigator",
        exam: [.direct("What caused {V}'s death?", "\"Fentanyl at a lethal level, in a pill that looked like a prescription pill but was counterfeit. {V} took it after a prom after-party.\""), .direct("How did you trace the pill?", "\"Through messages. They show {D} arranging a sale to a friend of {V}'s, and the pill matches counterfeit pills seized earlier.\""), .direct("Was {D} present that night?", "\"Not as far as we can tell. The sale was handed off, and a friend carried it to the party.\""), .direct("What did you find at the scene where {V} collapsed?", "\"{V} was found unresponsive in a bedroom around 1 a.m. after the after-party. Friends said {V} took one pill, and a second matching pill was in a pocket.\""), .direct("What did the autopsy conclude?", "\"Toxicology showed fentanyl at a lethal level and no other substance that would explain the death. {V} was pronounced dead at 1:30 a.m. at the hospital.\""), .direct("How did the messages lead you to {D}?", "\"A friend's phone had an exchange arranging a pill purchase, and the handle on the other end matched a number we tied to {D} in an earlier case.\""), .cross("Who handed off the pill?", "\"A friend. That person named {D} when questioned, and that person is the main link to {D}.\""), .cross("The messages are from earlier days, aren't they?", "\"Some of them are. They show {D} selling before that night, and I cannot say the exact date of the sale for this pill.\""), .cross("Was {D} identified by anyone who saw {D} that night?", "\"No. Nobody has said {D} was at the party or the after-party.\""), .cross("Did anyone describe the person who delivered the pill?", "\"The friend who carried it described a seller by name only. No one else described a face or a car.\""), .cross("Could the pill have come from somewhere else?", "\"I cannot rule it out. A second source is possible, but the pill matches counterfeit pills seized earlier, and the friend pointed us to {D}.\"")],
        defenseRole: "Co-worker",
        defenseExam: [.direct("Was {D} at work the night {V} died?", "\"Yes. {D} worked until ten that night. I was on shift and saw {D} the whole evening.\""), .direct("Could {D} have left earlier?", "\"Not without clocking out. We have a time clock and a manager who watches it.\""), .direct("How do you know {D} was still on the clock at 10?", "\"I saw the clock record. {D} was clocked in at ten and left around then.\""), .direct("What was your shift like that night?", "\"It was a busy Friday. We were short-staffed, so we stayed on the floor and rarely took breaks. I was in sight of {D} for most of it.\""), .direct("Do you remember {D} leaving?", "\"Only at the end of the shift. {D} punched out a little after ten and I said goodnight. Before that, {D} did not leave the building.\""), .direct("What can you tell the jury about {D}'s character at work?", "\"Reliable and on time. I have never seen {D} bring any drugs into the workplace or show up impaired.\""), .cross("Did you watch {D} every minute?", "\"No. We were busy. But {D} would have had to clock out to leave.\""), .cross("Could someone punch in for {D}?", "\"I do not think so. I never saw that happen, but I cannot rule it out.\""), .cross("Are you friends with {D}?", "\"We work together. We are friendly, but I am telling you what I saw.\""), .cross("How far from {D}'s station were you?", "\"In the same department, maybe thirty feet. I could not watch every second, but I would have noticed a long absence.\""), .cross("Does the time clock show you which door someone went through?", "\"No, it only shows when someone swipes in or out. A person could step outside for a few minutes without clocking out.\"")],
        theory: ("{D} sold the pill that killed.", "Another seller."),
        allocution: "\"I'm so sorry.\"",
        truths: ("The handoff friend named {DL}.", "{DL} was still clocked in at 10 p.m."),
        defendant: [.direct("Did you sell the pill that killed {V}?", "\"No. I was at work that night. I was not at any party and I never gave anyone a pill.\""), .direct("Where were you that night?", "\"At work until 10 p.m. I was on the clock, and my coworkers saw me there.\""), .direct("What about the messages?", "\"They were from earlier days and a different matter. They had nothing to do with that night.\""), .direct("Walk the jury through your evening on the day {V} died.", "\"I clocked in at my shift in the afternoon and was working the floor until 10 p.m. I did not leave early, and I went home afterward.\""), .direct("Who did you work with that night?", "\"A couple of co-workers and a shift lead. We stayed busy, and several of them talked to me during the shift.\""), .direct("What were the earlier messages about?", "\"They were earlier chats with that friend about an unrelated sale of a few pills. I will not pretend I was never involved in anything, but that night was different.\""), .cross("The friend who handed off the pill named you, didn't they?", "\"Yes, and I do not know why. They are lying, or they are confused.\""), .cross("You admit you sold pills before, don't you?", "\"I sold some earlier. I did not know any were counterfeit, and I would never have wanted anyone hurt.\""), .cross("A seventeen-year-old died. Do you feel any responsibility?", "\"I am sorry beyond words. But I was not there, and I did not sell that pill.\""), .cross("If you were at work, how did a pill arranged through your number end up with {V}'s friend?", "\"I do not know. Someone else may have used my name, or the friend may be covering for the real seller. I did not hand off anything.\""), .cross("Your phone was never with you on that shift?", "\"It was in my locker for most of the shift. I could not have been texting during my hours, and I did not.\"")],
        openings: ("A seventeen-year-old died after taking a counterfeit pill pressed with fentanyl outside a prom after-party. Messages tie the sale to {D}, and the pill matches counterfeit pills seized earlier.", "Listen for the defense evidence, which will show that {D} was clocked in at work at 10 p.m. and could not have been at the party. A friend's accusation is not proof."),
        closings: ("Fentanyl at a lethal level, counterfeit pills, and messages that tie the sale to {D}. A young person is dead because of a pill that {D} made available.", "A time clock says {D} was at work, and the only link to {D} is a friend who may be protecting someone. The State has not proved {D} sold that pill."),
        timeline: [(-1, "The sale is arranged."), (0, "10 p.m.: the handoff."), (0, "1 a.m.: {V} collapses."), (0, "1:30 a.m.: {V} is pronounced dead.")],
        identified: "Messages and toxicology.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "Our daughter is gone.",
        doctrines: ["alibi"],
        genders: ["V": .female])

    static let landlordRentThreat = SmallCases.make(
        key: "story.landlordRentThreat",
        category: .whiteCollar,
        headlines: ["Landlord Threatens Tenant With Deportation Unless Rent Is Raised", "Recording Captures Demand"],
        law: "extortion",
        threshold: 6,
        spec: "Threatened {V} with harm to reputation or status with intent to wrongfully obtain $1,200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A landlord, {D}, told {V}, a tenant, on {DATE} that {D.he} would report {V}'s family to immigration unless {V} paid an extra $1,200. A recording captured the demand. {DL} says it was only a warning about lease terms.",
        state: [E(.digital, 3, "Recording", "{D} says 'pay or I make a call.'"), E(.document, 2, "Lease", "No extra fee term."), E(.digital, 2, "Text", "Reminder of a deadline.")],
        defense: [E(.statement, 1, "Warning", "{DL} says it was lease talk.")],
        role: "Tenant",
        exam: [.direct("What did your landlord say to you?", "\"{D} said I had to pay an extra $1,200 or {D} would make a call about my family's immigration status. A recording captured it.\""), .direct("Does the lease have any such fee?", "\"No. The lease lists no extra fee of any kind. I read it carefully.\""), .direct("What did you do?", "\"I did not pay. I kept the recording and the texts, including a reminder of a deadline, and I went to deputies.\""), .direct("Where did the conversation happen, and who else was present?", "\"It was on the front steps of my building around 4 p.m. My family was inside. {D} came by to collect rent and raised the issue before I could say anything.\""), .direct("Tell us what you were feeling after hearing that.", "\"Frightened. My family's papers are our business, and {D} knew we worried about that. I did not know what the extra $1,200 was for.\""), .direct("How did you capture the recording?", "\"I turned on the voice recorder on my phone when {D} started talking about the fee. I saved the file at 4:30 and showed it to deputies the next day.\""), .cross("The recording does not mention immigration status by name, does it?", "\"The words are 'pay or I make a call.' It was clear to me what call was meant.\""), .cross("{D} says it was only a warning about lease terms, doesn't {D.he}?", "\"That is what {D} says. But the lease has no such term, and the demand was for money.\""), .cross("Had you been behind on rent?", "\"I was not behind. I had paid what the lease said I owed.\""), .cross("Did you pay any extra money to {D} after that?", "\"No. I told {D} I would read the lease again, and I did not hand over anything extra.\""), .cross("How do you know {D} meant immigration when the recording only says make a call?", "\"Because earlier that week {D} had mentioned my family's status in passing, and the call was not about anything else we discussed.\"")],
        defenseRole: "Property manager",
        defenseExam: [.direct("What was the policy at the property?", "\"There was no extra fee. The lease terms are standard, and nothing allows an added charge.\""), .direct("Did {D} ask you to collect an extra fee?", "\"Not that I recall. {D} never asked me to collect anything beyond the rent.\""), .direct("Did {D} raise other tenants' rent?", "\"Yes, three other tenants' rent was raised that year. I handled some of those notices.\""), .direct("How long have you managed this property?", "\"Six years. I handle rent collection, repairs, and the lease paperwork for most units in the building, so I know the lease terms well.\""), .direct("What notice goes out when a rent increase is planned?", "\"A written notice with the new amount and the effective date. The three increases that year went out that way, and none included an extra fee.\""), .direct("Did {V} ever complain to you about {D}?", "\"Not before the day of the recording. There were ordinary repair requests, and nothing about threats.\""), .cross("Was there any lease term that could justify $1,200?", "\"No. I do not know of one.\""), .cross("Did you hear the recording?", "\"I heard about it. I did not hear the original conversation.\""), .cross("Did {D} ever mention immigration to you?", "\"No. {D} never talked to me about anyone's immigration status.\""), .cross("Were you at the conversation on the steps?", "\"No. I was in the office, so I did not hear what was said between {D} and {V}.\""), .cross("Does {D} handle collection personally sometimes?", "\"Sometimes, yes. {D} does it when there is a dispute, and I would not always know what is said.\"")],
        theory: ("{D} extorted a tenant.", "A lease warning."),
        allocution: "\"I should not have said it.\"",
        truths: ("{DL} had raised three other tenants' rent.", "The recording never names immigration status."),
        defendant: [.direct("What did you mean by 'pay or I make a call'?", "\"I meant a call about the rules, about the lease. I was reminding {V.him} of the terms.\""), .direct("Why did you bring up immigration?", "\"It was a slip. I was frustrated and I said something I should not have.\""), .direct("What papers did you mean?", "\"The lease papers. I wanted {V.him} to read the lease and follow it.\""), .direct("Why did you go to see {V} that afternoon?", "\"To collect rent and to talk about damage to the unit and the number of people living there. I thought it was time to remind the tenants about the lease.\""), .direct("What did you want the tenants to do after the conversation?", "\"Read the lease and follow its terms. If they did not, I had the right to take lease action, and that is the call I meant.\""), .direct("What is your history with raising rent on this property?", "\"I raise rent on a schedule and give notice. I raised three other tenants' rents that same year, and none of them took it as a threat.\""), .cross("The lease has no fee for $1,200, does it?", "\"No. I thought there should be one for the damage and the extra occupants.\""), .cross("You asked for money and mentioned a call. How is that not a threat?", "\"I did not mean it as one. I was clumsy.\""), .cross("You raised three other tenants' rent too, didn't you?", "\"Yes, with notice. That is normal. This was a separate matter.\""), .cross("Why bring up an extra $1,200 if the lease has no such fee?", "\"I thought the damage and extra occupants justified it. I was wrong to ask without a clause, and I should have sent a proper notice.\""), .cross("You chose the words 'pay or I make a call.' You understand how that sounds to a tenant?", "\"I do now. At the time I was irritated and not thinking about how it would land on someone worried about their family.\"")],
        openings: ("A landlord, {D}, told {V}, a tenant, to pay an extra $1,200 or {D} would make a call about {V}'s family's immigration status. A recording captured the demand, and the lease has no such fee.", "The defense evidence includes a clumsy remark about lease terms and a recording that never names immigration status. {D} never meant to threaten anyone."),
        closings: ("'Pay or I make a call,' a lease with no extra fee, and a deadline text. That is a threat made to get money that was not owed.", "The recording never says immigration, and the lease talk was about rules. A clumsy remark is not extortion, and the State must prove a real threat."),
        timeline: [(-14, "The rent dispute begins."), (0, "4 p.m.: the demand."), (0, "4:30 p.m.: the recording is saved."), (1, "The report to deputies.")],
        identified: "A recording.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .sympathetic,
        impact: "We were afraid to open the door.",
        doctrines: ["burdenOfProof"])

    static let caretakerSavingsMove = SmallCases.make(
        key: "story.caretakerSavingsMove",
        category: .whiteCollar,
        headlines: ["Caretaker Moves Elderly Man's Savings Into Own Account", "Daughter Finds Empty Statements"],
        law: "exploitationElder",
        threshold: 8,
        spec: "Exploited a disabled adult by deception, obtaining $31,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, an eighty-four-year-old with memory loss, lost $31,000 over four months after {D}, a paid caretaker, moved funds into {D.his} own account. {DL} says {V} gave the money as a gift. The seven transfers came over four months, and a doctor's letter says {V} could not manage finances. {V}'s family reviewed the statements in the fourth month.",
        state: [E(.document, 3, "Bank Records", "Seven transfers into {D}'s account."), E(.document, 3, "Doctor's Letter", "{V} could not manage finances."), E(.digital, 2, "Texts", "{DL} asks {V} to 'sign again.'")],
        defense: [E(.statement, 1, "Gift", "{DL} says {V} wanted to give it.")],
        role: "Daughter",
        exam: [.direct("What did you find about my parent's money?", "\"{V}, who is eighty-four and has memory loss, lost $31,000 over four months. Seven transfers went into {D}'s account. We reviewed the statements in the fourth month.\""), .direct("Who is {DL}?", "\"{D} was {V}'s paid caretaker. {D} looked after {V} daily and had access to {V}'s accounts.\""), .direct("What do the texts show?", "\"{D} asks {V} to 'sign again.' A doctor's letter says {V} could not manage finances at that point.\""), .direct("How did you discover the transfers?", "\"In the fourth month my sibling and I sat down with the bank statements to sort bills. Seven transfers to one account stood out, each larger than a normal household expense.\""), .direct("What was {V}'s condition during those months?", "\"Memory loss that got worse. {V} forgot appointments, repeated stories within minutes, and could not follow a bank statement. The doctor's letter says the same.\""), .direct("What did you do after seeing the statements?", "\"We called the bank, then deputies. A week later {D} was charged. We moved {V}'s remaining funds into an account that needed two signatures.\""), .cross("{DL} says {V} gave the money as a gift, doesn't {D.he}?", "\"My parent never mentioned any gifts to me. And a doctor says {V} couldn't manage money.\""), .cross("Did you check on the statements earlier?", "\"No. I should have, yes. I trusted {D}. It wasn't until the fourth month that we reviewed the records.\""), .cross("Did {V} ever say anything about giving money away?", "\"{V} has memory problems, so what {V} says varies. I can't say {V} never said it, only that I never heard it.\""), .cross("Did {V} sign the transfer forms?", "\"The bank says so. I cannot tell you what {V} understood when signing, only that {V} could not balance a checkbook that year.\""), .cross("Did {D} ever hide being paid for caretaking?", "\"No, {D} was openly the paid caretaker and received a weekly wage. The transfers were on top of that wage.\"")],
        defenseRole: "Bank teller",
        defenseExam: [.direct("Did {V} come into the bank?", "\"Yes, several times, with {D}. They came for transfers, and {D} was always right there.\""), .direct("How did {V} behave?", "\"Polite and friendly. {V} sat down and signed what was put in front of {V}. {D} helped with the paperwork.\""), .direct("Did {V} seem to know what was happening?", "\"Hard to say. {V} smiled and went along with it. I didn't ask many questions.\""), .direct("How often did {V} visit your branch?", "\"About once every few weeks in those months. {D} usually drove, and they came to the counter together for transfers.\""), .direct("What is the procedure when a customer signs a transfer slip?", "\"We check ID, confirm the amounts, have the customer sign in front of us, and stamp it. These transfers followed that procedure.\""), .direct("Did {V} ever ask you a question about a transfer?", "\"Once, about the balance. {V} seemed pleasant and a little unsure, and {D} answered for {V} before I could.\""), .cross("Did {V} understand the transfers?", "\"I'm not sure. {V} didn't ask questions, and I didn't explain much. I can't say what {V} understood.\""), .cross("Did you notice anything concerning?", "\"Not at the time. Looking back, the pattern of visits was unusual. I didn't think much of it then.\""), .cross("Did {DL} do the talking?", "\"Mostly. {D} handled the conversation. {V} nodded and signed.\""), .cross("Did you ask {V} directly whether {V} understood the transfer?", "\"I asked if {V} wanted to go ahead, and {V} said yes. I did not ask more than that.\""), .cross("Did you ever flag the pattern to a supervisor?", "\"No. Looking back, seven transfers to one account in four months is a pattern. I did not report it.\"")],
        theory: ("{D} drained an elderly man.", "A gift."),
        allocution: "\"I helped too much.\"",
        truths: ("{DL} bought a truck with part of it.", "{V} signed each transfer slip in front of a teller."),
        defendant: [.direct("Why did you move money into your account?", "\"{V} wanted to give it to me as a gift. {V} said it several times, and I took that at face value.\""), .direct("Did you take advantage of {V}?", "\"No. I cared for {V} for a long time. I never meant to take anything {V} didn't want me to have.\""), .direct("What did you mean by 'sign again'?", "\"The bank needed signatures for the transfers. {V} signed them, and sometimes the form needed to be redone.\""), .direct("How did you come to care for {V}?", "\"I answered a posting for a live-in caretaker. For more than a year I cooked, drove {V} to appointments, and managed medications, and we grew very close.\""), .direct("When did {V} first mention giving you money?", "\"A few weeks into the winter. {V} said the extra help meant a lot and wanted to give something back, and the offer came up more than once.\""), .direct("What did the money pay for?", "\"Some of it went to everyday household bills and some to my own expenses. I did not keep a ledger, which I know was careless.\""), .cross("Seven transfers totaling $31,000, weren't there?", "\"Yes. That's a lot. {V} wanted to give it, and I accepted it. I know now I should have said no.\""), .cross("The doctor says {V} couldn't manage finances, doesn't {V.he}?", "\"That's what the letter says. {V} seemed clear to me on the good days. I didn't see it that way.\""), .cross("You never told the family about the gifts, did you?", "\"No. {V} asked me not to. I didn't think it was my job to explain.\""), .cross("You asked {V} to 'sign again,' meaning the first signature was not enough?", "\"The bank form had been filled in wrong, and the teller asked for it to be redone. That is all I meant by it.\""), .cross("Why not ask the family before taking $31,000?", "\"Because {V} said it was between us. I should have told them, and I see now how that looks.\"")],
        openings: ("{V}, eighty-four and living with memory loss, lost $31,000 over four months in seven transfers to {D}'s account. {D} was {V}'s paid caretaker. The State will present the family, the bank records, and a doctor's letter.", "The defense will point you to a caretaker who was close to {V} for a long time, a bank teller who saw {V} come in with {D}, and a claim that {V} wanted to give."),
        closings: ("Seven transfers, $31,000, a caretaker with access, and a doctor's letter saying {V} could not manage money. A gift that cannot be understood is not a gift.", "{V} came to the bank with {D} several times and signed each form. The State has not proved {V} lacked the capacity to give, or that {D} took anything by deceit."),
        timeline: [(-120, "The first transfer."), (0, "Month 4: the seventh transfer."), (0, "Month 4: the daughter reviews statements."), (0, "Week after: {DL} is charged.")],
        identified: "Bank records.",
        aggravating: ["The victim was particularly vulnerable", "The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "He trusted her with everything.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .female, "V": .male])

    static let custodyExchangeFlight = SmallCases.make(
        key: "story.custodyExchangeFlight",
        category: .violent,
        headlines: ["Father Drives Off With Toddler at Custody Exchange", "Car Found Two States Away"],
        law: "kidnapping2",
        threshold: 7,
        spec: "Unlawfully took and carried away {V}, a minor, without consent of the lawful custodian, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At a gas-station custody exchange on {DATE}, {D} buckled {V}, a three-year-old, into {D.his} car and left before the mother returned from the restroom. The court order gave the mother primary custody. {DL} says {D.he} feared for the child.",
        state: [E(.video, 3, "Station Camera", "{D} buckles the child and drives away."), E(.document, 3, "Custody Order", "Primary custody to the mother."), E(.digital, 2, "Toll Record", "The car crossed a state line.")],
        defense: [E(.statement, 1, "Fear", "{DL} says {D.he} feared for the child.")],
        role: "Mother",
        exam: [.direct("What happened at the gas station on {DATE}?", "\"It was a custody exchange. I stepped into the restroom for a moment, and when I came out, {D} had buckled {V} into the car and was gone.\""), .direct("What does the custody order say?", "\"I have primary custody of {V}, who is three. The custody order is a court document and is in evidence.\""), .direct("What did you learn about where {V} went?", "\"The car crossed a state line. The toll record shows the route. I didn't know where {V} was for some time.\""), .direct("Describe the exchange plan before that day.", "\"The order requires exchanges at this gas station at 5 p.m. I arrived on time and handed over the bag, then stepped into the restroom for a couple of minutes.\""), .direct("What did you see on the camera afterward?", "\"I watched the footage with the deputies. {D} lifted {V} into the car seat, buckled {V}, closed the door, and drove away at about 5:05.\""), .direct("What did you do when you realized {V} was gone?", "\"I ran out and shouted, then called 911. For hours I did not know where {V} was, and I could not sit still until {V} was found.\""), .cross("{DL} says {D.he} feared for the child, doesn't {D.he}?", "\"I never saw anything that would give {D} a reason to fear. {V} was safe with me.\""), .cross("Did {DL} get an emergency order?", "\"Not that I know of. {D} didn't go to court, and I wasn't told about any problem.\""), .cross("Were you away from {V} for long?", "\"Only a moment, in the restroom. I'd never leave {V} for long. It was a short exchange and I was inside a few minutes.\""), .cross("Had the two of you had arguments about exchanges before?", "\"Yes. There were disagreements about schedules, and the dispute had flared again that week. Nothing physical, but a lot of hard words.\""), .cross("Did {V} ever tell you about being left alone?", "\"I do not recall {V} saying that. {V} is three and does not explain things clearly, and I was not told of any concern.\"")],
        defenseRole: "Gas station clerk",
        defenseExam: [.direct("Were you working at the gas station that day?", "\"Yes. I was behind the counter and could see the lot through the front window.\""), .direct("What did you see between {DL} and {V}?", "\"{D} was calm. {D} buckled the child in without force and without any fuss. {V} wasn't crying.\""), .direct("Did anyone object?", "\"No. Nobody said a word. It looked like an ordinary exchange to me.\""), .direct("Where were you standing in relation to the pumps?", "\"At the register, with a clear view of pump three through the glass. It is not a big station, and the afternoon was quiet.\""), .direct("How would you describe the child's reaction?", "\"The child sat quietly and played with a toy. There was no screaming and no struggle, nothing that would catch your attention.\""), .direct("How long did the exchange take?", "\"A few minutes. The child was buckled in and the car left, and I did not think twice about it.\""), .cross("Did you know about the custody order?", "\"No. I didn't know anything about it. I only saw a person put a child in a car.\""), .cross("Did you hear what {DL} planned?", "\"No. I didn't hear any conversation. I couldn't have told you where {D} was going.\""), .cross("Were you watching the entire exchange?", "\"Not every second. I had customers. I saw most of it, but I can't say I saw all of it.\""), .cross("Did you notice the other parent come out of the restroom?", "\"Not until after the car had gone, when somebody started shouting in the lot. I was ringing up a customer at that point.\""), .cross("Would you have done something differently if you knew about the custody order?", "\"I would have called someone. I did not know, so I assumed it was a normal exchange between family members.\"")],
        theory: ("{D} took a child.", "A father's fear."),
        allocution: "\"I just wanted more time.\"",
        truths: ("{DL} had no emergency order.", "The child had told a teacher about being left alone."),
        defendant: [.direct("Why did you take {V}?", "\"I was afraid for {V}. I thought {V} wasn't safe. I buckled {V} in and drove away because I didn't know what else to do.\""), .direct("Did you plan to keep {V}?", "\"I didn't have a plan. I was scared, and I acted without thinking it through. I never meant to keep {V} from the custodian.\""), .direct("Where did you take {V}?", "\"I drove away, and I crossed a state line. I wanted to get {V} somewhere calm. I know that was wrong.\""), .direct("What was going through your mind during the exchange?", "\"I was frightened. I kept thinking about what {V} might be going through, and I could not stand the thought of handing {V} back that evening.\""), .direct("What did you do once you were on the road?", "\"I kept driving and stopped a few times to settle {V} down. I bought food and tried to keep things calm. {V} was not hurt.\""), .direct("How did the situation end?", "\"I was found, and {V} went back to the custodial parent. I told the deputies I was scared and that I had made a terrible decision.\""), .cross("There's a custody order, isn't there?", "\"Yes, I know about it. I should have followed it. I should have gone to court instead.\""), .cross("You left while {V}'s parent was in the restroom, didn't you?", "\"Yes. I waited for that moment, and I know it looks like I planned it. I wasn't thinking about the law.\""), .cross("You didn't call anyone to say where {V} was, did you?", "\"No. That is on me. I was frightened and I wasn't thinking.\""), .cross("You never tried to get an emergency order from a judge?", "\"No. I thought there was no time and did not know how to do it. I know now that was the right path.\""), .cross("Crossing the state line made it harder for the custodian to find {V}, didn't it?", "\"Yes. I did not think about that part, but I understand that it did. I am sorry for the fear it caused.\"")],
        openings: ("At a gas-station custody exchange, {D} buckled {V}, a three-year-old, into {D}'s car and drove away while the parent with primary custody was in the restroom. The car crossed a state line. The State will show the camera, the order, and the toll record.", "The defense will present a relative who believed the child was in danger, a clerk who saw a calm and gentle exchange, and no force or violence."),
        closings: ("A court order, a three-year-old taken while the custodian was in a restroom, and a car across a state line. {D} knew the order and took {V} anyway.", "A calm, gentle exchange and a person who feared for a small child. The State has not proved {D} meant to keep {V} from the person with custody."),
        timeline: [(-3, "A custody dispute is renewed."), (0, "5 p.m.: the exchange."), (0, "5:05 p.m.: {D} drives away."), (1, "The child is found.")],
        identified: "Camera and records.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .divided,
        impact: "I thought I'd never see {V} again.",
        doctrines: ["necessity", "lesserIncluded"],
        genders: ["D": .male, "V": .male])

    static let rooftopPharmacyBreakIn = SmallCases.make(
        key: "story.rooftopPharmacyBreakIn",
        category: .property,
        headlines: ["Thieves Cut Through Pharmacy Roof and Take Opioids", "Alarm Ignored by Wind"],
        law: "burglary2",
        threshold: 7,
        spec: "Broke and entered a building, a pharmacy owned by {V}, with intent to commit larceny, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A pharmacy roof was cut open on {DATE} and opioids valued at $18,000 were taken. A roofing saw was traced to {D}. {DL} says {D.he} sold the saw weeks earlier.",
        state: [E(.physical, 3, "Roofing Saw", "Saw blade matches the cut; sold to {D}.", .search), E(.video, 2, "Roof Camera", "A figure in a hood on the roof."), E(.document, 2, "Inventory", "$18,000 in opioids missing.")],
        defense: [E(.document, 1, "Receipt", "{DL}'s sale of the saw to a stranger.")],
        role: "Pharmacist",
        exam: [.direct("What was taken from your pharmacy?", "\"Opioids valued at about $18,000. The inventory count shows exactly what was missing.\""), .direct("How did the thief get in?", "\"Through the roof. The roof was cut open, and a figure in a hood appears on the roof camera.\""), .direct("What links {D} to the break-in?", "\"The blade of a roofing saw matches the cut in our roof, and the saw was sold to {D}. There is a receipt.\""), .direct("When did you discover the break-in?", "\"I came to open at 7 a.m. and found water stains and a hole in the ceiling tiles of the back room. The narcotics cabinet had been pried open and the shelves were bare.\""), .direct("What did the roof look like from above?", "\"A rectangular opening had been cut through the roofing and decking with a saw. The edges were clean and straight, which is why the deputies looked for a specific blade.\""), .direct("What does the roof camera show, and at what time?", "\"At about 2 a.m. a figure in a dark hood crosses the roof with a bag and kneels at the cut. The video is grainy, and the hood hides everything above the chin.\""), .cross("Can you identify the face on the roof camera?", "\"No. The hood covers the face, and the picture is small.\""), .cross("The saw was sold to {D}, not necessarily used by {D}, correct?", "\"That is correct. A saw can be sold again, and I cannot say who held it on the roof.\""), .cross("Did you see anyone on the roof?", "\"No. I found the damage in the morning, and I only know what the camera shows.\""), .cross("How big is the figure on the camera?", "\"Average height as far as I can tell, but there is nothing on the roof to measure against, so I would not put a number on it.\""), .cross("Did anything at the pharmacy carry {D}'s fingerprints?", "\"No. Nothing I was told about carried prints from {D}. The cabinet and the roof edge were handled with gloves, as far as anyone can tell.\"")],
        defenseRole: "Roofer",
        defenseExam: [.direct("Did {D} work with you on roofing jobs?", "\"Not recently. {D} worked with me a while ago but not in the past few months.\""), .direct("Did {D} still use the saw?", "\"Not that I saw. {D} told me the saw had been sold.\""), .direct("Did {D} borrow tools from you?", "\"No. {D} had tools of {D.his} own and did not borrow mine.\""), .direct("How long have you known {D}?", "\"About eight years. We worked a few jobs side by side and kept in touch, though not often in recent months.\""), .direct("What did {D} say about the saw?", "\"A few weeks before the break-in, {D} told me the saw was gone because rent was due. {D} did not say who bought it.\""), .direct("How would you describe {D}'s work habits?", "\"Hard working and on time. I never saw {D} take anything that was not part of a job, and I would hire {D} again.\""), .cross("Did you see {D} sell the saw?", "\"No. I did not see the sale itself. I only know {D} said it was sold.\""), .cross("Do you know who bought it?", "\"No. I do not know the buyer.\""), .cross("Were you with {D} the night of the break-in?", "\"No. I was not. I do not know where {D} was that night.\""), .cross("Did you ever see the saw after {D} said it was sold?", "\"No. I never saw it again, so I cannot tell you where it went or who had it.\""), .cross("Do you know where {D} was the night of the burglary?", "\"No. I was at home and I do not know where {D} was, so I cannot give an alibi.\"")],
        theory: ("{D} cut into a pharmacy.", "A sold saw."),
        allocution: "\"I'm ashamed.\"",
        truths: ("{DL} had used pills in the car.", "A neighbor watched a man buy the saw from {DL}."),
        defendant: [.direct("Did you break into the pharmacy?", "\"No. I did not cut that roof or take anything from the pharmacy.\""), .direct("What happened to the saw?", "\"I sold it weeks earlier. A buyer paid cash, and I did not keep a record of the sale.\""), .direct("Who bought it?", "\"I do not know the person's name. It was a cash sale, and I did not ask.\""), .direct("Where were you at 2 a.m. on the night of the break-in?", "\"Asleep at home. Nobody can say otherwise because I live alone, but I did not leave the house that night.\""), .direct("Why did you sell the saw?", "\"I needed money for rent. A buyer wanted a saw that day, so I let it go for cash and did not think about a receipt.\""), .direct("What can you tell the jury about the buyer?", "\"Not much. It was someone I met once about the saw, and I did not get a name or a number. I wish I had.\""), .cross("The blade matches the cut in the pharmacy roof, doesn't it?", "\"So the report says. It is my saw, but I did not use it that night.\""), .cross("You were found with pills in your car, weren't you?", "\"Those were mine. They are a separate matter from the pharmacy.\""), .cross("Why can't you name the buyer of the saw?", "\"I did not think I would need to. It was a quick sale.\""), .cross("A sale for cash with no name and no receipt. Isn't that convenient?", "\"It looks convenient now. At the time it was a quick sale between two people, and I had no idea I would ever have to prove it.\""), .cross("Your saw matches the cut in a pharmacy roof and you are a roofer. Why should the jury not conclude you used it?", "\"Because plenty of people can buy a saw, and I sold mine weeks before. I know how the match looks, but it does not tell you who held it.\"")],
        openings: ("A pharmacy roof was cut open and $18,000 in opioids taken. The blade of a roofing saw sold to {D} matches the cut, and a hooded figure appears on the roof camera.", "The defense evidence will establish that {D} sold the saw weeks earlier and that no face appears on the camera. A saw that changed hands is not proof of who used it."),
        closings: ("A roof cut with a saw sold to {D}, a hooded figure on camera, and $18,000 in opioids gone. {D} is the one connected to the tool.", "The saw was sold weeks before the break-in, and no face appears on the video. The State has traced a tool, not a burglar."),
        timeline: [(-14, "The saw is sold, {DL} says."), (0, "2 a.m.: the roof is cut."), (0, "7 a.m.: the pharmacist opens."), (1, "The saw is traced.")],
        identified: "A saw and a camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure"])

    static let hospitalBillingIdentity = SmallCases.make(
        key: "story.hospitalBillingIdentity",
        category: .whiteCollar,
        headlines: ["Hospital Billing Clerk Opens Credit Cards in Patients' Names", "Fraud Alerts Trace to One Terminal"],
        law: "identityTheft",
        threshold: 7,
        spec: "Knowingly obtained identifying information of {V} and used it to obtain credit, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Nine patients received credit card bills they never opened after {D}, a hospital billing clerk, copied their identifying information on {DATE}. Access logs tied each lookup to {D}'s terminal. {DL} says a shared password let others use it.",
        state: [E(.digital, 3, "Access Log", "Nine lookups at {D}'s terminal in two weeks."), E(.document, 3, "Card Applications", "Three cards mailed to a post office box."), E(.document, 2, "Box Rental", "The box was rented by {D}.")],
        defense: [E(.statement, 1, "Shared Login", "{DL} says the password was shared.")],
        role: "Hospital compliance officer",
        exam: [.direct("What did your compliance review find about nine patients?", "\"Nine patients received credit card bills for cards they never opened. We traced each lookup of their information to one terminal.\""), .direct("Whose terminal was it?", "\"{D}'s. The access log shows nine lookups at {D}'s terminal over two weeks, and {D} was a billing clerk.\""), .direct("What did the card applications show?", "\"Three cards were mailed to a post office box. The box rental shows it was rented by {D}.\""), .direct("How did the problem come to the compliance office?", "\"Patients began calling about credit card statements for cards they never opened. Several mentioned recent hospital stays, so we compared their names against our records.\""), .direct("What exactly was copied from the patient files?", "\"Names, dates of birth, and Social Security numbers, all fields that sit on the billing screen. Nothing about treatment was involved in these nine cases.\""), .direct("What did the access log show over those two weeks?", "\"Nine separate lookups from {D}'s terminal, each on a patient who later got a bill. Those patients had no other link to one another.\""), .cross("{DL} says the password was shared, doesn't {D.he}?", "\"Other clerks have used terminals. I can't rule out that someone else logged in.\""), .cross("Did you interview other clerks?", "\"Yes. Some said they used shared logins on occasion. It's a weakness in our system that we've since addressed.\""), .cross("Were all nine lookups at the same time of day?", "\"I don't have that to give you. They were spread across two weeks. I can't say they were all while {D} was at the desk.\""), .cross("Do you know who was sitting at the terminal during each lookup?", "\"No. The log records the login and the terminal, not a face. I cannot tell you who was at the keyboard.\""), .cross("How many clerks knew the shared password?", "\"From interviews, at least four people had seen it on a note near the terminal. That is a failing in our practices, and we corrected it.\"")],
        defenseRole: "Billing coworker",
        defenseExam: [.direct("Did others use {DL}'s terminal?", "\"Sometimes. When someone was out, others would sit at the nearest desk and use whatever was logged in.\""), .direct("Was the password shared?", "\"It was common to share. We'd tell each other the password to cover for someone. It's not allowed, but it happened.\""), .direct("Did you use it yourself?", "\"Once or twice, when I covered for {D}. I never looked up anything I shouldn't have.\""), .direct("How is the billing floor laid out?", "\"Six desks in a row with a printer in the middle. People walk between desks all day, and any terminal left logged in is fair game for a quick lookup.\""), .direct("Where was the password note kept?", "\"On a sticky note on the side of a monitor at {D}'s desk. Four or five of us glanced at it when we needed to cover a shift.\""), .direct("Did your supervisor ever address the sharing?", "\"Once, in a meeting after the incident. Before that, everyone treated it like normal housekeeping, and nobody was told to stop.\""), .cross("Did you look up those patients?", "\"No. I never looked up any of the nine. I'd remember if I had.\""), .cross("Do you know who did?", "\"No. I don't know who used the terminal when I wasn't there. I only know it wasn't me.\""), .cross("Did {DL} ever tell you about a post office box?", "\"No. We didn't talk about anything like that. I never heard of one.\""), .cross("Did you ever see anyone other than {D} using that login?", "\"I saw a coworker use it once during a break. I do not know whether others did when I was not looking.\""), .cross("Do you know about {D}'s post office box?", "\"No. I did not know {D} had one. Our conversations stayed on work and weekend plans.\"")],
        theory: ("{D} stole patients' identities.", "A shared login."),
        allocution: "\"I'm so sorry.\"",
        truths: ("The post office box was rented in {DL}'s name.", "The note was visible to four clerks."),
        defendant: [.direct("Did you copy those patients' information?", "\"No. I never copied anyone's information. I looked up accounts for billing, which is my job, and that's all.\""), .direct("Why would your terminal show those lookups?", "\"The password was shared. Several of us used the same login at times. Someone else could have used it.\""), .direct("Did you rent a post office box?", "\"I may have, for personal use. I don't remember cards being mailed to it. I never applied for any cards.\""), .direct("What does your job involve day to day?", "\"I pull up patient accounts to verify insurance, fix billing codes, and answer questions from the front desk. I open dozens of accounts in a shift.\""), .direct("How did the shared password come about?", "\"A note with the login was stuck near the terminal so whoever covered the desk could get in. Everyone knew about it, and nobody objected.\""), .direct("What did you do when you heard patients were affected?", "\"I was shocked and told my supervisor everything I knew, including about the password note. I said anyone nearby could have used the login.\""), .cross("The lookups were at your terminal, weren't they?", "\"That's what the log says. But the password was known to others. I don't know who used it.\""), .cross("The box was rented by you, correct?", "\"I rented one at some point. I didn't use it for those cards. I don't know how cards ended up there.\""), .cross("You're the one with access to patient data, aren't you?", "\"I'm one of several. It's my job. I'd never abuse it.\""), .cross("The post office box was rented by you, wasn't it?", "\"A box was rented in my name at some point. I used it for packages and mail from my own life, and I did not apply for cards.\""), .cross("Nine patients in two weeks is a pattern. Whose pattern is it if not yours?", "\"I cannot say. The login was mine on paper, but it was open to the desk. I would not look up nine strangers for no reason.\"")],
        openings: ("Nine hospital patients received credit card bills for cards they never opened, after nine lookups at {D}'s billing terminal in two weeks. Three cards were mailed to a post office box rented by {D}. The State will show the logs, the applications, and the box rental.", "The defense evidence includes a hospital system with a shared password, coworkers who used the same terminal, and a record that does not say who was at the keyboard."),
        closings: ("Nine lookups at {D}'s terminal, three cards to a post office box rented by {D}. The logs and the box lead to one person.", "A shared password means a shared login, and a log cannot say who typed. The State has the terminal and a box, but not proof of who used either one."),
        timeline: [(-20, "Lookups begin."), (0, "Week 2: applications mailed."), (0, "Week 3: patients report bills."), (0, "Week 4: {DL} is arrested.")],
        identified: "Logs and a rental record.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "I spent a year fixing my credit.",
        doctrines: ["burdenOfProof"])

    static let tavernTruckShots = SmallCases.make(
        key: "story.tavernTruckShots",
        category: .violent,
        headlines: ["Shots Fired Into Occupied Tavern From Passing Pickup", "Bullet Holes Above the Pool Table"],
        law: "dischargingOccupied",
        threshold: 7,
        spec: "Willfully discharged a firearm into an occupied building, a tavern owned by {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Four shots struck a tavern on {DATE} while twenty patrons were inside; no one was hurt. A pickup was seen leaving. Casings matched a pistol later found in {D}'s truck. {DL} says the pistol was stolen two days before.",
        state: [E(.forensic, 3, "Casings", "Match the pistol found in {D}'s truck."), E(.video, 2, "Street Camera", "A pickup leaving the lot."), E(.document, 2, "Barred Notice", "{D} was barred from the tavern a month earlier.")],
        defense: [E(.document, 1, "Theft Report", "{DL} reported the pistol stolen two days earlier.")],
        role: "Tavern owner",
        exam: [.direct("What happened at your tavern?", "\"Four shots hit the front wall while about twenty patrons were inside. Nobody was hurt, but people dove under tables.\""), .direct("Did you see who fired?", "\"No. I only heard the shots and saw a pickup leaving. The street camera caught it leaving the lot.\""), .direct("Why was {D} a suspect?", "\"{D} had been barred from the tavern a month earlier, and a pistol that matched the casings was found in {D}'s truck.\""), .direct("Where were you when the shots hit?", "\"Behind the bar, pouring a beer, about eleven at night. The first shot hit the front wall and the others followed in about two seconds.\""), .direct("What did you do and what damage did you find?", "\"I shouted for everyone to get down and called 911. Four holes had gone through the front wall and one shattered a glass display near a table.\""), .direct("What do you know about {D}'s history with the tavern?", "\"A month earlier I told {D} not to come back after a loud argument at the bar. I put it in writing, and {D} left angry.\""), .cross("Did you see the shooter's face?", "\"No. It was too dark and happened too fast.\""), .cross("The pistol was reported stolen, wasn't it?", "\"I have heard that it was. I do not know the details of the report.\""), .cross("Were many pickups like that in the area?", "\"Plenty of pickups look similar. The camera does not show a plate clearly.\""), .cross("How far was the pickup from your door when it left?", "\"The camera shows it leaving the lot, so within fifty feet of the entrance, but I was ducked down and did not see it myself.\""), .cross("Could someone else have had a grudge against the tavern?", "\"I run a busy bar, so people sometimes leave angry. I cannot name anyone else, but I cannot swear no one else could have.\"")],
        defenseRole: "Truck neighbor",
        defenseExam: [.direct("Where was {D}'s truck at 11 p.m.?", "\"At home. I could see it parked in the driveway when I looked out around 11.\""), .direct("How can you be sure?", "\"I live next door, and I noticed the truck because it was there when I closed my blinds.\""), .direct("Did you watch the truck all night?", "\"No. I did not. I only saw it at eleven.\""), .direct("How well do you know {D}?", "\"We have lived next door for six years. I see {D} most days, and we talk over the fence about the truck and the yard.\""), .direct("What did you see out your window around eleven?", "\"The truck parked in the driveway, the porch light on, and a light inside the kitchen. It looked like every other night.\""), .direct("Have you ever known {D} to be violent?", "\"No. {D} yells at ball games and that is about it. I have never seen {D} threaten anyone.\""), .cross("Did you see {D} at home?", "\"I saw the truck, not {D}. I cannot say who was in the house.\""), .cross("Could the truck have left after eleven?", "\"Yes, it could have. I went to bed and did not check.\""), .cross("How far is the tavern from {D}'s home?", "\"Not far. It is a few minutes' drive.\""), .cross("Did you see {D} get out of the truck that night?", "\"No. I did not see {D} at all. I only saw the vehicle, and I cannot say who might have driven it later.\""), .cross("Do you know about the stolen pistol?", "\"Only what I have heard. {D} did not tell me about the theft, and I do not know when it was taken.\"")],
        theory: ("{D} shot into a tavern.", "A stolen pistol."),
        allocution: "\"Nobody was meant to be hurt.\"",
        truths: ("The theft report was filed after the shooting.", "A second pistol was never found."),
        defendant: [.direct("Did you fire the shots at the tavern?", "\"No. I did not fire any shots. I was not there that night.\""), .direct("Why was a pistol in your truck?", "\"It was my pistol, and it was stolen two days before. I found it in my truck later.\""), .direct("When did you file the theft report?", "\"After the shooting. I did not notice it was gone until then.\""), .direct("How did you learn the pistol was gone?", "\"I opened the glove box looking for my registration and the pistol was not there. That was after deputies stopped my truck and asked about it.\""), .direct("Where were you at eleven that night?", "\"At home, about ten minutes from the tavern, watching a game. I did not drive anywhere until the deputies pulled me over that night.\""), .direct("How do you feel about the ban from the tavern?", "\"I was angry, and I will say so. But I took it as a bar owner's call and found somewhere else to drink.\""), .cross("You were barred from that tavern a month earlier, weren't you?", "\"Yes. I was upset about it, but I would never shoot at a building full of people.\""), .cross("The casings match the pistol in your truck. Isn't that proof?", "\"It proves the pistol was used. It does not prove I used it. It was stolen.\""), .cross("You waited to report the theft until after the shooting. Why?", "\"I did not notice it was missing. I only looked when I heard about the shots.\""), .cross("The pistol was in your truck when deputies found it. Why does the jury believe it was ever stolen?", "\"Because I filed a report. I had left the truck unlocked, and I believe someone took it and brought it back before the stop.\""), .cross("A theft report after the shooting looks like a cover story. Why should anyone believe it?", "\"I understand why you ask. I reported it as soon as I knew it was gone, and I had no way to make that sound better.\"")],
        openings: ("Four shots struck a tavern while twenty patrons were inside. A pickup was seen leaving, the casings match a pistol later found in {D}'s truck, and {D} had been barred from the tavern a month earlier.", "The defense will present evidence that the pistol was stolen two days before and that {D}'s truck was parked at home. No one saw the shooter."),
        closings: ("Four shots at a crowded tavern, a pickup leaving, casings that match a pistol in {D}'s truck, and a grudge over a ban. The evidence points to {D}.", "A pistol stolen two days earlier, a truck at home, and no one who saw the shooter. The State cannot show {D} fired a shot."),
        timeline: [(-30, "{DL} is barred."), (0, "11 p.m.: four shots."), (0, "11:20 p.m.: a pickup is stopped."), (0, "Next day: the pistol is matched.")],
        identified: "Ballistics and a truck.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        doctrines: ["alibi"])

    static let fishPlantGhostPayroll = SmallCases.make(
        key: "story.fishPlantGhostPayroll",
        category: .whiteCollar,
        headlines: ["Plant Payroll Manager Pays Employees Who Do Not Exist", "Auditor Finds Twelve Ghost Checks"],
        law: "embezzlement100k",
        threshold: 8,
        spec: "Embezzled over $100,000 belonging to {V}, a seafood plant, by a person in a position of trust, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A seafood plant lost $127,000 over two years through payroll checks to employees who never worked there. {D}, the payroll manager, approved every check. Checks were cashed at one bank branch. {DL} says an owner's son set up the names.",
        state: [E(.document, 3, "Payroll Audit", "Twelve names never worked at the plant."), E(.document, 3, "Bank Deposits", "Checks deposited to an account in {D}'s spouse's name."), E(.digital, 2, "Approval Log", "{D}'s approval on each.")],
        defense: [E(.statement, 1, "Owner's Son", "{DL} says the owner's son set up the names.")],
        role: "Plant controller",
        exam: [.direct("What did your payroll audit find at the plant?", "\"Over two years, we lost $127,000 in payroll checks to twelve names who never worked at the plant.\""), .direct("Who approved those checks?", "\"{D}, the payroll manager, approved every one. The approval log shows {D}'s approval on each check.\""), .direct("Where did the checks go?", "\"They were cashed at one bank branch, and the deposits went to an account in {D}'s spouse's name.\""), .direct("How long did the scheme run, and how did you notice it?", "\"Two years. A new accountant noticed that twelve employees had no time cards and no job titles, and the audit confirmed none had ever worked at the plant.\""), .direct("How did the approval process work?", "\"Each check required one approval in the payroll system tied to a login. {D}'s approval is on every one of the checks, with the date and time stamped.\""), .direct("What did the bank deposits show?", "\"Checks for the twelve names were cashed or deposited at one branch, and the money moved into an account in {D}'s spouse's name within days.\""), .cross("{DL} says a member of the owner's family set up the names, doesn't {D.he}?", "\"I know the owner's relative gave a list for a seasonal crew at one point. I can't say about the rest.\""), .cross("Could someone else have used {DL}'s approval?", "\"The approval screen is tied to {D}'s login. I can't say whether someone else could use it.\""), .cross("Did you notice earlier?", "\"Not until the audit. The checks looked normal on their face. It took cross-checking the names against actual work.\""), .cross("Did anyone else have access to payroll entries?", "\"A few people could view the screens, but only {D} and one backup could approve. I cannot say whether the backup logged in then.\""), .cross("Why did the audit not catch it earlier?", "\"The total each month stayed within the normal range, and the names looked like seasonal workers. We trusted the process too much.\"")],
        defenseRole: "Owner's son",
        defenseExam: [.direct("What did you do with payroll?", "\"I gave a list of seasonal crew names to the payroll office. I gave it to {D} so the workers could be paid.\""), .direct("Did you add names beyond that?", "\"No. Only the list for the seasonal crew. I never gave names I didn't know.\""), .direct("Did you approve any checks?", "\"Never. I don't have access to the approval screen. I wouldn't know how to use it.\""), .direct("What is your role at the plant?", "\"I help out in the office and on the dock, mostly with scheduling and deliveries. I am not on payroll or accounting.\""), .direct("What was the list you gave {D} for?", "\"A seasonal crew for the busy months. I wrote down the names of people the owner hired through a temp contact.\""), .direct("How can you be sure you did not enter more names?", "\"I do not have an account on the payroll system. I only gave a piece of paper, and I never typed anything in.\""), .cross("Did you give the list in writing?", "\"I think so. It's been a while. I don't have a copy of it.\""), .cross("Do you work at the plant often?", "\"I help out. I'm not there every day, and I don't know the whole payroll.\""), .cross("Are you related to the owner?", "\"Yes. I'm the owner's child. I know that makes it look like I'd defend the business, but I'm telling the truth.\""), .cross("Do you still have a copy of that list?", "\"No. I handed over the only paper, and I did not keep a photo of it. I cannot show it to the jury.\""), .cross("Did you ever check whether those seasonal workers showed up?", "\"No. That was a management matter. I assumed the crew boss had them working.\"")],
        theory: ("{D} stole from the plant.", "The owner's son."),
        allocution: "\"I regret all of it.\"",
        truths: ("The account was opened with {DL}'s spouse.", "The son never touched the approval screen."),
        defendant: [.direct("Did you add those names to payroll?", "\"No. The owner's relative gave me names for a seasonal crew. I entered what I was given. I didn't invent anyone.\""), .direct("Did you approve the checks?", "\"Yes, I approved checks in the course of my job. I approved what was in the system. I didn't know the names weren't real.\""), .direct("What about the account in your spouse's name?", "\"I don't know anything about that. My spouse has accounts of our own. I never deposited those checks.\""), .direct("How long have you run payroll at the plant?", "\"Eleven years. I handle roughly ninety employees each cycle, enter hours, and approve the batch before it goes to the bank.\""), .direct("How did the seasonal names get into the system?", "\"The owner's family member handed me a list for a seasonal crew, and I entered the names exactly as I was given them. I did not question the list.\""), .direct("What happened when the audit started?", "\"I was suspended the next week. I cooperated, gave them my login history, and told them about the list I had entered.\""), .cross("You approved every check, didn't you?", "\"That's my job. I approved what came through. I didn't verify each name, and I know I should have.\""), .cross("The deposits went to your spouse's account, didn't they?", "\"That's what the records say. I don't know how. I didn't tell my spouse to deposit them.\""), .cross("$127,000 over two years is a lot, isn't it?", "\"It is. I'm shocked. I'm not the one who took it.\""), .cross("Twelve names and not one time card, and you never asked who they were?", "\"I should have asked. The list came from the owner's family, and I assumed the hours were handled by the crew boss.\""), .cross("The account that received the money is in your spouse's name. Do you expect the jury to ignore that?", "\"I expect them to ask who opened it. I did not deposit those checks, and my spouse did not tell me about them.\"")],
        openings: ("A seafood plant lost $127,000 over two years in payroll checks to twelve people who never worked there. {D}, the payroll manager, approved every check, and the deposits went to an account in {D}'s spouse's name. The State will show the audit and the bank records.", "The defense will present a legitimate list of seasonal workers, an owner's relative who never touched approvals, and an account that never ties to {D}'s own hand."),
        closings: ("Twelve fake names, $127,000, {D}'s approval on every check, and deposits into an account in {D}'s spouse's name. The trail does not leave {D}'s desk.", "Approving a check does not mean knowing the name is fake. The State has not proved {D} created the names or controlled the account."),
        timeline: [(-700, "Ghost names are added."), (0, "Year 2: the audit begins."), (0, "Week after: {DL} is suspended."), (0, "Month later: indictment.")],
        identified: "Audit and deposits.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "Layoffs followed.",
        doctrines: ["burdenOfProof"])

    static let countyFuelDepotSkim = SmallCases.make(
        key: "story.countyFuelDepotSkim",
        category: .property,
        headlines: ["County Fuel Depot Loses Thousands of Gallons Over Months", "Attendant's Truck Seen Filling Barrels"],
        law: "felonyLarceny",
        threshold: 7,
        spec: "Stole diesel fuel valued at $23,000 belonging to {V}, a county, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A county fuel depot lost 6,000 gallons of diesel over four months. A camera showed {D}, an attendant, filling barrels in a pickup after hours. {DL} says the barrels were for county mowers.",
        state: [E(.video, 3, "Depot Camera", "{D} fills barrels at night."), E(.document, 3, "Inventory Log", "6,000 gallons unaccounted for."), E(.physical, 2, "Barrels", "County-marked barrels at {D}'s farm.", .search)],
        defense: [E(.statement, 1, "Mowers", "{DL} says the barrels were for county mowers.")],
        role: "County finance officer",
        exam: [.direct("What did the county find at its fuel depot?", "\"Over four months, we lost 6,000 gallons of diesel. The inventory log shows it as unaccounted for.\""), .direct("What does the depot camera show?", "\"{D}, an attendant, filling barrels in a pickup at night, after hours. It happened on camera more than once.\""), .direct("What was found at {DL}'s farm?", "\"County-marked barrels. Deputies recovered them during a search at {D}'s farm.\""), .direct("How does the depot normally track fuel?", "\"Every pump transaction is recorded with a card, a time, and a gallon total. Deliveries are logged the same way, so our books should balance each month.\""), .direct("How was the shortage first noticed?", "\"The month four audit compared the delivered totals with the pumped totals. The gap was 6,000 gallons over four months, and it kept growing each month.\""), .direct("What did you see on the video from the depot?", "\"On several nights after the gate was shut, {D} fills barrels in the bed of a pickup using the depot pump and then drives off with them.\""), .cross("{DL} says the barrels were for county mowers, doesn't {D.he}?", "\"We do fuel mowers, but through the depot's normal process, not from barrels at night.\""), .cross("Could {DL} have been authorized for after-hours fueling?", "\"I'm not aware of any authorization. I haven't found any approval in our records.\""), .cross("Did you count every barrel?", "\"I counted what was recovered. I can't tell you every gallon is accounted for. It was a lot of fuel.\""), .cross("Did the barrels carry county markings?", "\"Yes. The ones recovered did. That could mean they were used for county work, or it could just be how the barrels were first bought.\""), .cross("Do you have records showing the diesel was sold?", "\"No. We have no sales records or deposits that show the fuel was sold. We only know it left the depot and where some barrels ended up.\"")],
        defenseRole: "Road crew foreman",
        defenseExam: [.direct("Do mowers need fuel?", "\"Yes. Our mowers go through a lot of diesel in season. We rely on the depot for supplies.\""), .direct("How do crews get their fuel?", "\"Normally from the depot during business hours. {D} handled the depot's fuel for us.\""), .direct("Did {DL} deliver fuel to you?", "\"In the past, yes. It was part of the arrangement. I know the depot attendant has been helpful.\""), .direct("How many mowers does your crew run in season?", "\"Eight, plus a couple of tractors with brush hogs. In July we go through a lot of diesel, and we cannot afford to run dry.\""), .direct("How did your crew usually get fuel in the past?", "\"We drove the trucks to the depot and had {D} fill up. Sometimes {D} left a few cans for us by the gate.\""), .direct("How would you describe {D} as an employee?", "\"Helpful, and a little casual with procedure. {D} was never sloppy about safety, but {D.he} sometimes skipped the paperwork.\""), .cross("Did {DL} fuel your mowers recently?", "\"Not since spring. That's the last time I remember getting a delivery.\""), .cross("Did you ask {DL} to fill barrels at night?", "\"No. I never asked for fuel after hours. I wouldn't have known about any barrels.\""), .cross("Do you know about 6,000 gallons going missing?", "\"Only what I've heard. I didn't know about any of it until I was asked to testify.\""), .cross("Did anyone on your crew ever fill barrels from the depot at night?", "\"Not to my knowledge. If it happened it was between {D} and some other crew, and I did not ask.\""), .cross("How many gallons did your crew use over those four months?", "\"I would have to check, but it was nowhere near 6,000. We burn a few hundred gallons a week at most.\"")],
        theory: ("{D} took county fuel.", "Mower fuel."),
        allocution: "\"I thought no one would care.\"",
        truths: ("Barrels were found on {DL}'s farm.", "No mower had been fueled from them."),
        defendant: [.direct("Why were you filling barrels at night?", "\"I was filling them for county mowers. The crews needed fuel for the next day, and I did it after hours to save time.\""), .direct("Why were the barrels at your farm?", "\"I took them home to keep until the crews picked them up. It was a convenience. I didn't use the diesel for myself.\""), .direct("Did you take diesel for yourself?", "\"No. I'd never steal from the county. I thought I was helping out. It was part of how I got things done.\""), .direct("What was your job at the depot?", "\"I was the attendant. I logged deliveries, ran the pump for crews, and made sure the tanks were topped off. I had keys to the gate.\""), .direct("Why did you fill barrels after hours instead of during the day?", "\"The mower crews started early and the lines at the pump got long. I filled barrels the night before so they could grab and go.\""), .direct("How did the barrels end up at your farm?", "\"I kept some there overnight until a crew could swing by. I stored them in my shed because the depot yard was cramped.\""), .cross("You filled barrels after hours, didn't you?", "\"Yes. I know that's not by the book. I thought it was fine because it was for county use.\""), .cross("The barrels were county-marked, weren't they?", "\"Yes, because they were county barrels. They stayed county property. I never sold any of the fuel.\""), .cross("6,000 gallons is a lot of mower fuel, isn't it?", "\"Yes. But there are a lot of mowers. I never kept track of the amount, and I know I should have.\""), .cross("Did you write any of those night fillings into the depot log?", "\"No. I know I should have. I knew they were not recorded, and I let them go because I thought I was helping.\""), .cross("If you were only helping, why would you hide it by working after hours?", "\"I was not hiding it. I did it after hours because that is when I had time, and I did not stop to think about the paperwork.\"")],
        openings: ("A county fuel depot lost 6,000 gallons of diesel over four months. Camera footage shows {D}, an attendant, filling barrels in a pickup after hours, and county-marked barrels were found at {D}'s farm. The county will offer the depot video, the pump and delivery log, and the barrels recovered from a farm.", "Jurors will also see an attendant who filled barrels for county mowers and a crew foreman who knows mowers use a lot of fuel. The State must prove {D} kept it for personal gain."),
        closings: ("Six thousand gallons unaccounted for, an attendant filling barrels at night, and those barrels at {D}'s farm. The county's fuel went home with {D}.", "Barrels, mowers, and a county-marked trail. {D} filled barrels openly on camera, and the State has not proved {D} kept the fuel."),
        timeline: [(-120, "Fuel starts disappearing."), (0, "Month 4: the audit."), (0, "Month 4: the camera shows barrels."), (1, "{DL} is suspended.")],
        identified: "Camera and inventory.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"])

    static let stagedCrashClaim = SmallCases.make(
        key: "story.stagedCrashClaim",
        category: .whiteCollar,
        headlines: ["Insurer Says Crash With Parked Truck Was Staged", "Both Drivers Share a Phone Plan"],
        law: "insuranceFraud",
        threshold: 7,
        spec: "Presented a false claim to an insurer, {V}, seeking $42,000 for a staged collision, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} claimed $42,000 after a low-speed crash with a parked truck on {DATE}. The truck's owner and {D} shared a phone plan and had called each other forty times. {DL} says they met at a shop and the crash was an accident.",
        state: [E(.digital, 3, "Phone Records", "Forty calls between the drivers."), E(.document, 3, "Claim File", "$42,000 for injuries."), E(.video, 2, "Intersection Camera", "A slow-speed tap.")],
        defense: [E(.statement, 1, "Accident", "{DL} says it was an accident.")],
        role: "Insurance investigator",
        exam: [.direct("What did the intersection camera show?", "\"A slow-speed tap between {D}'s car and a parked truck. It looks like a minor bump, not a serious crash.\""), .direct("What did {D} claim?", "\"$42,000 for injuries. The claim file includes a doctor's note about neck pain.\""), .direct("Why did you suspect the crash was staged?", "\"The phone records show forty calls between {D} and the truck's owner, who also share a phone plan.\""), .direct("What first made the claim stand out to you?", "\"The damage photos showed a minor scuff while the claim asked for $42,000 in injury costs. That gap is the first thing that flagged the file.\""), .direct("What did you do to look into it?", "\"I pulled the intersection camera, the claim file, and the phone records. The camera showed a slow tap with no braking, and the records showed repeated calls.\""), .direct("What do the phone records show about the timing of the calls?", "\"Forty calls over about three months, many on the days before the collision. Several calls came the evening before and the morning after.\""), .cross("Calls between customers of the same shop are not unusual, are they?", "\"They can be. But forty calls and a shared plan between a driver and the owner of a parked truck is unusual.\""), .cross("Did a doctor confirm injuries?", "\"Yes. A doctor confirmed neck pain. I do not dispute that {D} saw a doctor.\""), .cross("Do you have anything beyond phone calls?", "\"The joint account and the calls. I do not have a recorded conversation about staging a crash.\""), .cross("Is a joint account proof of a plan?", "\"No. It shows a financial tie, but it does not tell me what the account was used for. I cannot say it was used to plan a crash.\""), .cross("Did the treating doctor say anything suspicious about the neck pain?", "\"No. The doctor's note records neck pain and a plan for treatment. I have no evidence that the doctor knew of any staging.\"")],
        defenseRole: "Body shop owner",
        defenseExam: [.direct("Do {D} and the truck's owner know each other?", "\"They are both customers of my shop. I have seen each of them in my waiting area over the years.\""), .direct("Are they related, as far as you know?", "\"I do not know. I have never heard either of them talk about being family or even close friends.\""), .direct("Did they ever come into the shop together?", "\"Not that I recall. They came in on different days, and I did not see them talking to each other.\""), .direct("What kind of work does your shop do?", "\"Collision repair and paint. We see both minor dents and big wrecks, and we keep records on every vehicle that comes through.\""), .direct("Did you do any work on the truck or on {D}'s car after this crash?", "\"The truck had a small scuff and a bent bumper bracket, and I estimated a few hundred dollars. {D}'s car had a similar scuff on the front.\""), .direct("How does damage from a low-speed tap normally look?", "\"Scuffed paint, a cracked bumper cover, and sometimes a bent bracket. It is minor, but people can still feel it in the neck.\""), .cross("Did you ever hear them discuss the crash?", "\"No. I did not hear any conversation about a crash, staged or otherwise, at my shop.\""), .cross("Do you know why they called each other forty times?", "\"No. I know nothing about their calls, and I would not want to guess about it.\""), .cross("How long have you known the two of them?", "\"A couple of years each. I know them only from repair work and not from anything outside the shop.\""), .cross("Is it unusual for someone to claim injuries after a tap like that?", "\"It happens. Some people are sore afterward, and some are not. I cannot tell you whether any given claim was fair.\""), .cross("Did you see {D} and the truck owner together at your shop?", "\"Only separately that I recall. I never saw them talk, so I cannot tell you how close they were.\"")],
        theory: ("{D} staged a crash.", "An accident."),
        allocution: "\"I made a bad decision.\"",
        truths: ("The two had a joint account.", "The doctor confirmed neck pain."),
        defendant: [.direct("Was the crash staged?", "\"No. It was an accident. I tapped the truck, and I did not plan it.\""), .direct("How do you know the other driver?", "\"From a shop. We have both been customers there, and we got to know each other.\""), .direct("Why forty calls?", "\"Business. We talked about work and about a loan. It had nothing to do with the crash.\""), .direct("Describe the collision as you remember it.", "\"I was pulling into a spot and my foot slipped on the pedal. The car rolled into the parked truck at a crawl, and I felt a jolt in my neck.\""), .direct("What did you do after the crash?", "\"I got out, checked the truck, and called the owner right away since I knew the number. We exchanged insurance information, and I went to a doctor the next morning.\""), .direct("How did you know the truck owner before the crash?", "\"We met at the body shop a couple of years back and later talked about splitting a loan. That is why we shared a phone plan.\""), .cross("You share a phone plan with the owner of a parked truck you hit. Isn't that a coincidence?", "\"We share a plan because of a loan. I did not think it would look odd.\""), .cross("You have a joint account with this person, don't you?", "\"Yes, for a loan. It was a business arrangement.\""), .cross("A slow tap and $42,000 in injuries. Doesn't that seem excessive?", "\"I felt the pain after. The doctor confirmed it. I did not make it up.\""), .cross("You called the truck owner forty times in three months. What were those calls about?", "\"Mostly the loan and some work questions. I have not kept a list, but I would not call it a secret.\""), .cross("The crash happened at a crawl and you claimed $42,000. How does a tap like that cost that much?", "\"The claim covered treatment and time away from work. I did not set the amount, and I did what the doctor told me to do.\"")],
        openings: ("{D} claimed $42,000 for injuries after a slow-speed tap with a parked truck. Phone records show forty calls between {D} and the truck's owner, who share a phone plan.", "The defense case is that the two knew each other from a shop and a loan, that a doctor confirmed neck pain, and that the crash was an accident."),
        closings: ("A slow tap, forty calls, a shared plan, a joint account, and a $42,000 claim. These facts describe a crash that was planned.", "A real tap, a real doctor, and two people who know each other through a shop. The State has shown a connection, not a plan to defraud."),
        timeline: [(-30, "The drivers meet."), (0, "1 p.m.: the collision."), (0, "Next day: the claim."), (30, "The investigator flags the claim.")],
        identified: "Records and claim file.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let diningWitnessThreat = SmallCases.make(
        key: "story.diningWitnessThreat",
        category: .violent,
        headlines: ["Man Threatens Witness at Diner Days Before Trial", "Waitress Overhears Warning"],
        law: "witnessIntimidation",
        threshold: 7,
        spec: "Threatened {V}, a witness, to deter testimony in a pending case, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Days before {D}'s assault trial, {V}, the state's witness, was approached in a diner on {DATE}. A waitress heard {D} say {V} would 'regret' testifying. {DL} says {D.he} only asked {V} to tell the truth.",
        state: [E(.statement, 3, "Waitress", "'You'll regret testifying.'"), E(.video, 2, "Diner Camera", "{D} leans over {V}'s table."), E(.document, 2, "Subpoena", "{V} was subpoenaed days earlier.")],
        defense: [E(.statement, 1, "Truth", "{DL} says {D.he} asked {V} to be honest.")],
        role: "Waitress",
        exam: [.direct("What did you hear in the diner on {DATE}?", "\"{D} leaned over {V}'s table and said, 'You'll regret testifying.' I was nearby and heard it clearly.\""), .direct("What does the diner camera show?", "\"{D} leaning over {V}'s table. You can see the posture and how close {D} was to {V}.\""), .direct("What do you know about the case?", "\"{V} had been subpoenaed days earlier as a witness in {D}'s assault trial. It was just days before the trial.\""), .direct("Where were you standing when {D} came in, and what were you doing?", "\"I was working the counter section near the front window, refilling coffee for a table about ten feet from {V}'s booth. It was around 1 p.m. and the diner was half full.\""), .direct("Describe how {D} approached {V}.", "\"{D} walked straight to {V}'s table, put a hand on the back of the booth, and leaned in close. {V} stopped eating and sat very still.\""), .direct("What did {V} do after the conversation?", "\"{V} left a few dollars on the table and hurried out about 1:20. I could see {V}'s hands shaking as {V} picked up a purse and keys.\""), .cross("Did {DL} shout?", "\"No. {D} spoke in a low voice. That's why I made a point of listening. It wasn't loud.\""), .cross("{DL} says {D.he} only asked {V} to tell the truth, doesn't {D.he}?", "\"I heard 'regret.' I'm telling you what I heard, and I can't speak to anything else.\""), .cross("Could you hear the whole conversation?", "\"No. I heard part of it. I was refilling coffee nearby, and I caught that phrase.\""), .cross("Did you hear how the conversation began?", "\"No. I caught the middle of it as I came around with the pot. The start and whatever {V} said back are lost to me.\""), .cross("Was the diner noisy at that hour?", "\"Moderately. There was a dish clatter and some chatter, so I will not claim I heard every word, only the one sentence I have already described.\"")],
        defenseRole: "Diner cook",
        defenseExam: [.direct("Were you at the diner that day?", "\"Yes, I was working in the kitchen. I could see parts of the dining room through the pass-through window.\""), .direct("Did you see {DL} talk to {V}?", "\"Yes. {D} stopped at {V}'s table and spoke for a moment. {D} didn't shout or make a scene.\""), .direct("Did {DL} seem angry?", "\"Not from what I saw. {D} seemed nervous. It looked like a short, quiet conversation.\""), .direct("How long have you cooked at this diner?", "\"Close to four years. I work the grill and look out through the pass-through when it gets slow. I know the regulars by their orders.\""), .direct("What could you see from the kitchen window?", "\"Most of the front booths and the aisle. I could see {D} standing by {V}'s table with no one else near.\""), .direct("How did {D} leave?", "\"Calmly. {D} straightened up, sat at the counter, and ordered a drink. There was no hurry and no slamming of doors.\""), .cross("Could you hear what was said?", "\"Not clearly. I was in the kitchen. I could see them, but I couldn't make out the words.\""), .cross("Could {DL} have said something threatening?", "\"I can't say. I didn't hear it. I only saw how {D} acted.\""), .cross("Were you watching the whole time?", "\"No. I had orders to cook. I looked up now and then. I can't say I saw every second.\""), .cross("Did you see {V}'s face during the conversation?", "\"Only from the side. {V} looked down, but I could not read the expression from that distance.\""), .cross("Did you know {D} before that day?", "\"I knew the face from the neighborhood but not the name. I had no reason to take {D}'s side or against it.\"")],
        theory: ("{D} threatened a witness.", "A plea for honesty."),
        allocution: "\"I was scared.\"",
        truths: ("{DL} had a pending trial date.", "{V}'s hands shook on camera."),
        defendant: [.direct("Why did you speak to {V} at the diner?", "\"I saw {V} and wanted to talk. I was nervous about the trial. I only wanted to ask {V} to tell the truth.\""), .direct("What did you say to {V}?", "\"I said something like, tell the truth. I didn't say 'regret.' I'd never intend to threaten a witness.\""), .direct("How did {V} react?", "\"{V} looked uncomfortable and turned away. I realize now that I shouldn't have approached {V} at all.\""), .direct("Where did you first see {V} that day?", "\"I saw {V} through the diner window as I walked by on my way to lunch. On impulse I went in and approached the booth.\""), .direct("What had been on your mind that week?", "\"The trial was set for days later, and I was scared of what would happen. I kept thinking about what {V} would say on the stand.\""), .direct("How long did the conversation last?", "\"Maybe thirty seconds. I said my piece, {V} looked away, and I walked out to the counter and ordered a drink.\""), .cross("You knew {V} was a witness, didn't you?", "\"Yes. I knew. That's why I shouldn't have gone over. It was a mistake.\""), .cross("The waitress says 'regret' was said, doesn't the waitress?", "\"The waitress may have heard something. I don't remember saying it. I didn't mean it as a threat.\""), .cross("The trial was only days away, wasn't it?", "\"Yes. I was anxious. I wasn't thinking about how it looked. I should have stayed away.\""), .cross("You walked into a diner and went straight to a person who had been subpoenaed against you. What did you expect to accomplish?", "\"Honestly, I wanted {V} to remember how things really were. I was not thinking about what the law says about approaching witnesses.\""), .cross("The camera shows you leaning over {V}'s table. Does that look like a casual hello?", "\"No. I leaned in because I was nervous and did not want the whole diner to hear. I can see how that looks bad.\"")],
        openings: ("Days before {D}'s assault trial, {D} leaned over the state's witness, {V}, at a diner and, according to a waitress, said {V} would regret testifying. The diner camera shows it. The State will present the waitress and the video.", "The defense will point you to a quiet, brief conversation, a cook who saw no shouting, and a person who says {D.he} only asked {V} to tell the truth."),
        closings: ("A subpoenaed witness, a trial days away, and {D} leaning over {V}'s table to say {V} would regret testifying. That is a threat to a witness.", "No shouting, no touching, and a conversation no one heard in full. The State has not proved {D} threatened {V} rather than urged honesty."),
        timeline: [(-4, "{V} is subpoenaed."), (0, "1 p.m.: the diner."), (0, "1:20 p.m.: {V} leaves."), (1, "{V} calls deputies.")],
        identified: "Waitress and camera.",
        aggravating: ["The offense involved a threat"],
        mood: .wantsConviction,
        impact: "I was afraid to testify.",
        doctrines: ["relevance"],
        genders: ["D": .male])

    static let highSchoolPostThreat = SmallCases.make(
        key: "story.highSchoolPostThreat",
        category: .violent,
        headlines: ["Student Posts Threat of Shooting at Rival High School", "Account Traced to Family Computer"],
        law: "massViolenceThreat",
        threshold: 7,
        spec: "Threatened to commit mass violence on educational property, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A post appeared on {DATE} promising a shooting at a high school football game. The account traced to a family computer belonging to {D}, a nineteen-year-old. {DL} says a younger sibling posted it as a joke.",
        state: [E(.digital, 3, "Post", "'Friday night they won't forget.'"), E(.digital, 3, "Account Trace", "Traced to a computer in {D}'s home."), E(.document, 2, "Sibling Interview", "The sibling denies posting.")],
        defense: [E(.statement, 1, "Joke", "{DL} says a sibling posted it.")],
        role: "Detective",
        exam: [.direct("What did the post say, and when did it appear?", "\"On {DATE}, a post promised a shooting at a high school football game: 'Friday night they won't forget.' It caused a lot of alarm.\""), .direct("How did you trace the post?", "\"The account traced to a computer in {D}'s home. {D} is nineteen. The trace is documented in the account records.\""), .direct("What did the sibling say?", "\"The sibling was interviewed and denied posting it. That interview is in the file.\""), .direct("What steps did you take after the post appeared?", "\"I secured the post and the account records, notified the school's security staff, and asked for the account's login history to see which device was used.\""), .direct("What did the login history show?", "\"Every login came from one internet address assigned to {D}'s family home, including the login at 5 p.m. when the post went up.\""), .direct("What happened at the game on Friday?", "\"The game started late while deputies swept the stadium and checked bags at the gate. Many families stayed home, and attendance was far below normal.\""), .cross("{DL} says a younger sibling posted it as a joke, doesn't {D.he}?", "\"The sibling denies it, but the sibling is a minor and may have been afraid to say.\""), .cross("Does the trace prove who was at the keyboard?", "\"No. It shows the computer in the home. Anyone in the household could have used it.\""), .cross("Did you find any plan or weapon connected to {DL}?", "\"No. I found no evidence of a plan. I found no weapon. I only have the post and the trace.\""), .cross("Did you find any messages from {D} about harming anyone?", "\"No. {D}'s phone and accounts showed no plan and no talk of violence. The post is the only piece of evidence of a threat.\""), .cross("How many people live in {D}'s home?", "\"Four, including {D} and a younger sibling, and all of them use that internet connection and the family computer.\"")],
        defenseRole: "Coach",
        defenseExam: [.direct("Do you coach {DL}'s sibling?", "\"Yes. I coach the team, and {D}'s sibling is on it. We practice after school most days.\""), .direct("Where was the sibling on the day of the post?", "\"At practice until six. I was there. I take attendance and watch every player.\""), .direct("How is the sibling as a player?", "\"Dedicated, friendly, and well-liked by the team. I've never seen any sign of violence.\""), .direct("How long have you coached the team?", "\"Seven years. I keep a roster and a sign-in sheet at every practice, and I know each player and their families.\""), .direct("What is the sibling's attendance like?", "\"Very good. The sibling is rarely late and stays through the cooldown. I took roll that day and the sibling was marked present.\""), .direct("What did you see of the sibling's behavior around the time of the post?", "\"Nothing unusual. The sibling joked around with teammates as usual and talked about the game, with no sign of anger.\""), .cross("Were you watching every minute?", "\"Almost. I have a lot of players. I can't say I had eyes on every one every second.\""), .cross("Could the sibling have posted from a phone?", "\"I suppose so. They have a phone. I don't know what they did on it during breaks.\""), .cross("Did you hear about the post?", "\"Only afterward. I learned about it when deputies asked me about practice.\""), .cross("How long did practice run that afternoon?", "\"Until about six. The posting time was 5 p.m., so I cannot give you an exact picture of every moment someone had a phone out.\""), .cross("Do players use their phones during practice?", "\"They are supposed to leave them in bags, but during water breaks some of them check them. I do not police that closely.\"")],
        theory: ("{D} threatened a school.", "A sibling's joke."),
        allocution: "\"I never meant it.\"",
        truths: ("{DL}'s login was used.", "The sibling was at practice."),
        defendant: [.direct("Did you write that post?", "\"No. I did not. I would never threaten a school or a game. It makes me sick to think about it.\""), .direct("Who do you think posted it?", "\"My sibling. They use the family computer, and I think it was a joke that got out of hand. I never saw them do it.\""), .direct("How did you feel when you learned about it?", "\"Horrified. I told the deputies right away what I thought. I wanted it cleared up.\""), .direct("What was your evening like on the day of the post?", "\"I got home from work around 5:30 and ate dinner. I was on my phone most of the evening and did not log in to that account.\""), .direct("How is the family computer used at home?", "\"It sits in the living room. My sibling plays games on it and everyone uses it for school and homework. The login stays saved.\""), .direct("How did you find out about the post?", "\"A friend texted me a screenshot the next day. I told my parents, and we went to the sheriff's office before anyone came to our door.\""), .cross("The post came from your family's computer, didn't it?", "\"Yes. That's what they told me. But more than one person uses it.\""), .cross("You're nineteen, aren't you?", "\"Yes. I'm old enough to be charged as an adult. That's why I'm so worried about this.\""), .cross("Your sibling denies posting it, doesn't {D.he}?", "\"Yes. I don't know why. I think they're afraid. I can't prove it.\""), .cross("The account is in your name, isn't it?", "\"Yes, I made it years ago, and the password was written down on a sheet near the computer. Anyone in the house could have used it.\""), .cross("If your sibling posted it, why won't your sibling say so?", "\"I think my sibling is scared and ashamed. I am not trying to pin it on anyone, and I would never want my sibling in trouble.\"")],
        openings: ("A post promised a shooting at a high school football game on Friday night. The account traces to a computer in {D}'s home, and {D} is nineteen. The State will show the post and the trace.", "The defense will present a shared family computer, a younger sibling who uses it, and a coach who places the sibling elsewhere at the time. A computer cannot tell who typed."),
        closings: ("A threat of a shooting, posted from a computer in {D}'s home. The sibling denies it, and {D} is an adult. The trace leads to the household, and {D} is the adult in it.", "The family computer is used by more than one person, and a trace doesn't name a person. The State has no plan, no weapon, and no proof {D} wrote that post."),
        timeline: [(-1, "The post appears."), (0, "5 p.m.: the post."), (0, "Friday: the game is delayed."), (0, "Saturday: {DL} is arrested.")],
        identified: "A trace.",
        aggravating: ["The offense involved a threat to a school"],
